  System.out.println("NATIVE_PO_SMOKE|PASS|WMS_EVENTS_NOT_ENABLED|NO_DOCACTION_OR_FACT_ACCT_CREDIT");
 }
 public void stop(BundleContext context){DB.closeTarget();System.out.println("NATIVE_DB_TARGET_CLOSED");}
}

