/**
 * P01.C03.T0029 (P01.T355) A-2 (spec {@code 05_} §3.3) — procesul {@code EVA_NotaSetWms}: nota de ambalare / dezambalare a unui set în
 * gestiunea WMS pereche W a gestiunii contabile G, în tranzacția procesului (un refuz sau o eroare ⇒ nimic scris). Fără document
 * contabil ({@code M_Production}, {@code M_StorageOnHand} neatinse): doar rândurile {@code EVA_StocWms} / {@code EVA_MiscareWms}, prin
 * {@code StocWms.inregistreaza}, o singură dată, cu {@code AD_Table_ID} = {@code AD_PInstance} și {@code Record_ID} = instanța.
 * Pașii {@code doIt}, în ordine: dreptul ({@link #areDrept}, aceeași funcție ca butonul, X207); firma; perechea; lacătul (firmă, W)
 * ÎNAINTEA citirilor; cererea ({@code NotaSetWms.refuzCerere}); definiția (regula T354 + lotul); la dezambalare rândul setului citit
 * FĂRĂ blocare + {@code refuzSet} (garda autoritară = {@code R_NEGATIV} în {@code StocWms.aplica}); piesele; la ambalare disponibilul
 * pe poziții și alocarea, pe aceeași hartă fără «Expediere» (D-11c-2); scrierea. Toate citirile și scrierea trec prin {@link Surse} (producția {@link #BAZA};
 * testul: cârligul {@link #surseTest}, X216 / X225).
 */
public class NotaSetWmsProces extends SvrProcess {

    public static final String VALUE = "EVA_NotaSetWms";
    public static final String P_GESTIUNE = "M_Warehouse_ID", P_TIP = "EVA_TipNota", P_SET = "M_Product_ID", P_CANTITATE = "Qty",
            P_POZITIE = "M_Locator_ID", P_VERSIUNE = "PP_Product_BOM_ID";
    /** Valorile parametrului {@link #P_TIP}. */
    public static final int TIP_AMBALARE = 1, TIP_DEZAMBALARE = 2;
    public static final String R_DREPT = "t355.refuz.drept", R_FARA_PERECHE = "t355.refuz.fara_pereche",
            R_DEFINITIE = "t355.refuz.definitie", K_GATA = "t355.nota.gata";

    private int gestiune, tipNota, set, k, locator, bom;

    /** Citirile și scrierea procesului (producția = {@link #BAZA}; în test o dublă care înregistrează apelurile și argumentele). */
    public interface Surse {
        int procesId();

        Boolean acces(Properties ctx, int proces);

        int tabelaInstanta();

        PerecheWms pereche(int client, int g, String trx);

        void lacat(String cheie, String trx);

        Set<Integer> locatori(int client, int w, String trx);

        /** [IsBOM, IsStocked, ProductType] sau {@code null} dacă articolul nu e al firmei. */
        Object[] produs(int client, int set, String trx);

        List<Integer> liste(int client, int set, String trx);

        List<SetLista.RandLista> randuri(int client, int bom, String trx);

        int cuLot(int client, int bom, String trx);

        BigDecimal cantitateSet(int client, int locator, int set, int bom, String trx);

        Map<Integer, BigDecimal> piese(int client, int set, int bom, String trx);

        Map<Integer, BigDecimal> pePozitii(int client, int w, int piesa, String trx);

        Map<Integer, Integer> prioritate(int client, int w, String trx);

        AlegerePozitii.Ordine ordine(int client, String trx);

        String codProdus(int produs, String trx);

        String codLocator(int locator, String trx);

        void inregistreaza(Properties ctx, int client, List<MiscareWms> miscari, String trx);
    }

    /** Cârligul testului (X216 / X225): vizibil doar în pachet, implicit {@code null}, nicio atribuire în {@code src}. */
    static Surse surseTest = null;

    static Surse surse() {
        return surseTest != null ? surseTest : BAZA;
    }

    /** Regula PURĂ a dreptului: procesul există și rolul are acces citire-scriere ({@code getProcessAccess} = TRUE). */
    public static boolean drept(int proces, Boolean acces) {
        return proces > 0 && Boolean.TRUE.equals(acces);
    }

    /**
     * Dreptul rolului sesiunii pe procesul {@link #VALUE} (D-05a-1 varianta b), O SINGURĂ funcție chemată de buton și de proces
     * (X207 / M-15); rolul prin {@code MRole.get} (X268).
     */
    public static boolean areDrept(Properties ctx) {
        Surse s = surse();
        int proces = s.procesId();
        return drept(proces, proces > 0 ? s.acces(ctx, proces) : null);
