/**
 * Base class to help simplify implementation of OSGi {@link EventHandler}.
 * @author hengsin
 *
 */
public abstract class AbstractEventHandler implements EventHandler {

	protected IEventManager eventManager = null;

	/**
	 * @see org.osgi.service.event.EventHandler#handleEvent(org.osgi.service.event.Event)
	 */
	@Override
	public void handleEvent(Event event) {
		Properties context = null;
		try {
			if (event.containsProperty(IEventManager.EVENT_CONTEXT)) {
				Properties eventContext = (Properties) event.getProperty(IEventManager.EVENT_CONTEXT);
				context = ServerContext.getCurrentInstance();
				ServerContext.setCurrentInstance(eventContext);
			}
			doHandleEvent(event);
		} catch (RuntimeException e) {
			addError(event, e);
			throw e;
		} catch (Exception e) {
			addError(event, e);
			throw new RuntimeException(e);
		} catch (Error e) {
			addError(event, e);
			throw e;
		} catch (Throwable e) {
			addError(event, e);
			throw new Error(e);
		} finally {
			if (context != null) {
				ServerContext.setCurrentInstance(context);
			}
		}
	}

	/**
	 * @param eventManager
	 */
	public void bindEventManager(IEventManager eventManager) {
		this.eventManager = eventManager;
		initialize();
	}

	/**
	 * @param eventManager
	 */
	public void unbindEventManager(IEventManager eventManager) {
		this.eventManager = null;
		eventManager.unregister(this);
	}

	/**
	 * Sub class should override this method to handle event.
	 * @param event
	 */
	protected abstract void doHandleEvent(Event event);

	/**
	 * Sub class should override this method to register event that the class want to listen to
	 */
	protected abstract void initialize();

	/**
	 *
	 * @param eventTopic
	 */
	protected void registerEvent(String eventTopic) {
		this.registerEvent(eventTopic, null);
	}

	/**
	 *
	 * @param topic
	 * @param filter
	 */
	protected void registerEvent(String topic, String filter) {
		if (filter != null)
			eventManager.register(topic, filter, this);
		else
			eventManager.register(topic, this);
	}

	/**
	 * @param topic
	 * @param tableName
	 */
	protected void registerTableEvent(String topic, String tableName) {
		String filter = "(tableName="+tableName+")";
		registerEvent(topic, filter);
	}

	/**
	 * @param topic
	 * @param classOrUUID className or ProcessUUID
	 */
	protected void registerProcessEvent(String topic, String classOrUUID) {
		String prop = "processUUID";
		try {
			UUID.fromString(classOrUUID);
		} catch (Exception e) {
			prop = "className";
		}
		String filter = "("+prop+"="+classOrUUID+")";
		registerEvent(topic, filter);
	}

	/**
	 * @param event
	 * @return PO
	 */
	protected PO getPO(Event event) {
		return EventHelper.getPO(event);
	}

	/**
	 * @param event
	 * @return ProcessInfo
	 */
	protected ProcessInfo getProcessInfo(Event event) {
		return EventHelper.getProcessInfo(event);
	}

