public final class StocWms {

    private StocWms() {
    }

    public static final String R_NEGATIV = "t331.stoc.refuz.negativ", R_CONFLICT = "t331.stoc.refuz.conflict";

    /** Rândul blocat al unei chei: id, cantitate, revizie. */
    public record Rand(int id, BigDecimal qty, int revizie) {
    }

    /** Accesul la bază al scrierii (interfață, ca testul să numere salvările fără bază). */
    public interface Depozit {
        Set<Integer> locatori(int client, int whWms);

        boolean produsActiv(int client, int produs);

        void lacat(String cheie);

        Rand citesteBlocat(int client, int locator, int produs, int asi, int bom);

        void scrieStoc(int client, int whWms, int locator, int produs, int asi, int bom, BigDecimal qty, Rand vechi);

        void scrieMiscare(int client, MiscareWms m);

        /** Codul produsului pentru textul refuzului (dubla testului: id-ul). */
        default String codProdus(int produs) {
            return String.valueOf(produs);
        }
    }

    // ───────────────────────────────────────────── scrierea

    public static void inregistreaza(Properties ctx, int client, List<MiscareWms> miscari, String trx) {
