    static final class Oprit extends Exception {
        private static final long serialVersionUID = 1L;
        final String loc;

        Oprit(String loc) {
            super(loc);
            this.loc = loc;
        }
    }

    /**
     * T21 D-R2-3: un PAS al unui job lung (ex. generarea unei declarații în «Verificare închideri»), opribil la pasul
     * curent. Fanionul se citește înaintea pasului și, cât timp pasul rulează (în firul lui, cu contextul sesiunii
     * copiat), la fiecare {@code intervalMs}: la oprire jobul NU mai așteaptă pasul și aruncă {@link Oprit} cu locul.
     * Pasul aflat în lucru nu e întrerupt — procesul nativ își termină singur tranzacția —, iar {@code cheieInCurs}
     * (dacă e dată) rămâne ocupată până la capătul lui, ca o rulare nouă să nu-l dubleze.
     *
     * @return rezultatul pasului
     * @throws Oprit oprirea a fost cerută înainte sau în timpul pasului
     * @throws Exception excepția pasului
     */
    static <T> T pasOpribil(String loc, java.util.concurrent.Callable<T> lucru, java.util.function.BooleanSupplier oprire,
                            long intervalMs, String cheieInCurs) throws Exception {
        if (oprire.getAsBoolean())
            throw new Oprit(loc);
        if (cheieInCurs != null)
            while (!ocupa(cheieInCurs)) {
                // pasul abandonat de rularea anterioară încă rulează: se așteaptă, opribil
                if (oprire.getAsBoolean())
                    throw new Oprit(loc);
                Thread.sleep(intervalMs);
            }
        final Properties ctx = new Properties();
        ctx.putAll(Env.getCtx());
        final java.util.concurrent.CompletableFuture<T> f = new java.util.concurrent.CompletableFuture<>();
        Thread fir = new Thread(() -> {
            org.adempiere.util.ServerContext.setCurrentInstance(ctx);
            T rez = null;
            Throwable err = null;
            try {
                rez = lucru.call();
            } catch (Throwable t) {
                err = t;
            } finally {
                org.adempiere.util.ServerContext.dispose();
                // cheia se eliberează ÎNAINTEA rezultatului: pasul următor al jobului o găsește liberă
                if (cheieInCurs != null)
                    elibereaza(cheieInCurs);
            }
            if (err == null)
                f.complete(rez);
            else
                f.completeExceptionally(err);
        }, "eva-pas-" + loc);
        fir.setDaemon(true);
        try {
            fir.start();
        } catch (RuntimeException ex) {
            if (cheieInCurs != null)
                elibereaza(cheieInCurs);
            throw ex;
        }
        while (true) {
            try {
                return f.get(intervalMs, java.util.concurrent.TimeUnit.MILLISECONDS);
            } catch (java.util.concurrent.TimeoutException asteapta) {
                if (oprire.getAsBoolean())
                    throw new Oprit(loc);
            } catch (java.util.concurrent.ExecutionException e) {
                Throwable c = e.getCause();
                if (c instanceof Exception)
                    throw (Exception) c;
                if (c instanceof Error)
                    throw (Error) c;
                throw new IllegalStateException(c);
            }
        }
    }

