     * confirmării duble ({@link com.eva.ro.contab.fiscal.AlarmaLunaViitoare.Marcaj}) pus pe firul care execută
     * {@code processIt} și scos în {@code finally} — NU un parametru de proces (un apel REST nu-l poate falsifica).
     */
    public static Rezultat ruleaza(Properties ctx, String valoare, String titlu, ProcessInfoParameter[] parametri,
            com.eva.ro.contab.fiscal.AlarmaLunaViitoare.Marcaj marcaj) {
        com.eva.ro.contab.fiscal.AlarmaLunaViitoare.pune(marcaj);
        try {
            return ruleazaIntern(ctx, valoare, titlu, parametri);
        } finally {
            com.eva.ro.contab.fiscal.AlarmaLunaViitoare.scoate(marcaj);
        }
    }

    private static Rezultat ruleazaIntern(Properties ctx, String valoare, String titlu, ProcessInfoParameter[] parametri) {
        int procId = DB.getSQLValue(null, "SELECT AD_Process_ID FROM AD_Process WHERE Value=?", valoare);
        if (procId <= 0)
            return new Rezultat(false, Etichete.t("decl.gen.proces_lipsa", valoare), null);
        ProcessInfo pi = new ProcessInfo(titlu, procId);
        pi.setAD_Client_ID(Env.getAD_Client_ID(ctx));
        pi.setAD_User_ID(Env.getAD_User_ID(ctx));
        pi.setParameter(parametri);
        // T21 D-R2-2: lansarea comună din ecran — la eșec instanța AD_PInstance se închide (lanseaza)
        Iesire r = lanseaza("EvaProcEcran", valoare, pi,
                trx -> new MProcess(ctx, procId, null).processIt(pi, trx), INCHIDE_IN_BAZA);
        Exception ex = r.exceptie;
        if (ex != null)
            return new Rezultat(false, Etichete.t("decl.gen.exceptie", valoare, DeclaratieEcran.radacina(ex)), null);
        boolean ok = r.ok;
        List<String> jurnal = new ArrayList<>();
        ProcessInfoLog[] logs = pi.getLogs();
        if (logs != null)
            for (ProcessInfoLog l : logs)
                if (l.getP_Msg() != null)
                    jurnal.add(l.getP_Msg());
        return new Rezultat(ok, pi.getSummary(), jurnal);
    }

