    /** Tipurile care pot purta o lipsă ({@code EVA_CantitateLipsa}, Î-C-2): ieșirile oglinzii și stornarea (20_ C-5). */
    public static final Set<TipMiscareWms> CU_LIPSA = EnumSet.of(TipMiscareWms.IESIRE, TipMiscareWms.LIVRARE, TipMiscareWms.STORNARE);

    /** PUR: {@code cantitateLipsa > 0} (null ⇒ fără lipsă). */
    public boolean areLipsa() {
        return cantitateLipsa != null && cantitateLipsa.signum() > 0;
    }

    /** PUR: mișcarea poartă doar lipsa (Qty = 0, lipsă > 0, tip din {@link #CU_LIPSA}) — nu atinge stocul, se scrie doar în jurnal. */
    public boolean doarLipsa() {
        return qty != null && qty.signum() == 0 && areLipsa() && CU_LIPSA.contains(tip);
    }

    /** Contextul citit al validării: firma, W, locatorii lui W, produsele active. */
