    }

    public static final String R_FIRMA = "t331.stoc.refuz.firma", R_TIP = "t331.stoc.refuz.tip", R_CANTITATE = "t331.stoc.refuz.cantitate",
            R_LOCATOR = "t331.stoc.refuz.locator", R_PRODUS = "t331.stoc.refuz.produs";

    /** Tipurile venite din oglinda documentelor contabile: scutite de condiția «produs activ» (04_ F-5, OglindaWms). */
    public static final Set<TipMiscareWms> DIN_OGLINDA = EnumSet.of(TipMiscareWms.RECEPTIE, TipMiscareWms.IESIRE, TipMiscareWms.LIVRARE,
            TipMiscareWms.STORNARE);

    /**
     * PUR: cheia refuzului (tradusă de apelant) sau null = mișcarea e permisă. Condițiile, în ordine: firma determinată și aceeași W
     * ca a contextului; tipul dat; {@code Qty > 0}, sau {@code Qty = 0} doar cu lipsă pe un tip din {@link #CU_LIPSA}, lipsa ≥ 0 și
     * numai pe tipurile {@link #CU_LIPSA} (20_ C-5); cel puțin un locator (fără locator doar mișcarea {@link #doarLipsa()}) și fiecare locator dat al lui W (nu al altei gestiuni, nici
     * același de / la); produsul activ (scutite tipurile oglinzii). Cantitatea peste stoc o refuză scrierea ({@code t331.stoc.refuz.negativ}).
     */
    public static String refuz(MiscareWms m, ContextValidare c) {
        if (c == null || c.client() <= 0 || m == null || m.gestiuneWms() <= 0 || m.gestiuneWms() != c.gestiuneWms())
            return R_FIRMA;
        if (m.tip() == null)
            return R_TIP;
        if (m.qty() == null || m.qty().signum() < 0 || m.qty().signum() == 0 && !m.doarLipsa()
                || m.cantitateLipsa() != null && m.cantitateLipsa().signum() < 0 || m.areLipsa() && !CU_LIPSA.contains(m.tip()))
            return R_CANTITATE;
        if (m.locatorDe() <= 0 && m.locatorLa() <= 0 ? !m.doarLipsa() : m.locatorDe() == m.locatorLa())
            return R_LOCATOR;
        if (m.locatorDe() > 0 && !c.locatoriW().contains(m.locatorDe()) || m.locatorLa() > 0 && !c.locatoriW().contains(m.locatorLa()))
            return R_LOCATOR;
        if (!DIN_OGLINDA.contains(m.tip()) && !c.produsActiv().test(m.produs()))
            return R_PRODUS;
        return null;
    }
