package com.eva.ro.contab.wms;

import java.util.List;
import java.util.Properties;

import org.adempiere.exceptions.AdempiereException;
import org.compiere.util.CacheMgt;

/**
 * P01.C03.T0017 (P01.T331) A-1 (04_ F-2, F-4; 05_ §3.1) — tabelele perechii WMS: legătura G ↔ W ({@code EVA_PerecheWms}), stocul
 * validat ({@code EVA_StocWms}) și jurnalul mișcărilor ({@code EVA_MiscareWms}), cu indexurile unice. Specificațiile sunt PURE;
 * {@link #ensureTables} le creează prin tiparul comun al pluginului ({@code EvaMetadata.ensureTabelaSpec}: AD_Table + AD_Column +
 * sincronizarea pe rolul System, cu retragerea coloanei fără corp fizic, X202), idempotent (a doua pornire ⇒ 0).
 */
public final class ModelWms {

    private ModelWms() {
    }

    public static final String PERECHE = "EVA_PerecheWms", STOC = "EVA_StocWms", MISCARE = "EVA_MiscareWms";

    private static final int REF_STRING = 10, REF_INTEGER = 11, REF_DATETIME = 16, REF_YESNO = 20, REF_NUMBER = 22;

    /** EVA_PerecheWms — un rând pe gestiunea contabilă activată (F-2). */
    public static final Object[][] COL_PERECHE = {
        {"M_Warehouse_ID", REF_INTEGER, 0, "G, gestiunea contabilă (EVA_TipEvidenta CV sau gol)"},
        {"EVA_GestiuneWms_ID", REF_INTEGER, 0, "W, perechea WMS (EVA_TipEvidenta NC)"},
        {"EVA_LocatorReceptie_ID", REF_INTEGER, 0, "zona «Recepție» a lui W"},
        {"EVA_LocatorExpediere_ID", REF_INTEGER, 0, "zona «Expediere» a lui W"},
        {"EVA_LocatorNeamplasat_ID", REF_INTEGER, 0, "zona «Neamplasat» a lui W"},
        {"EVA_DataActivare", REF_DATETIME, 0, "momentul activării"},
    };

    /** EVA_StocWms — stocul validat pe W × locator × produs × lot × versiunea listei de materiale (F-4). */
    public static final Object[][] COL_STOC = {
        {"M_Warehouse_ID", REF_INTEGER, 0, "W"},
        {"M_Locator_ID", REF_INTEGER, 0, "locatorul lui W (raft sau zonă)"},
        {"M_Product_ID", REF_INTEGER, 0, "piesa sau setul"},
        {"M_AttributeSetInstance_ID", REF_INTEGER, 0, "lotul (0 până la T329)"},
        {"PP_Product_BOM_ID", REF_INTEGER, 0, "0 pe piese; pe set = versiunea listei de materiale de la ambalare (09_ D-7)"},
        {"Qty", REF_NUMBER, 0, "cantitatea validată, >= 0"},
        {"EVA_Revizie", REF_INTEGER, 0, "revizia rândului, +1 la fiecare scriere (B8)"},
    };

    /** EVA_MiscareWms — jurnalul mișcărilor stocului validat, doar adăugare (F-4). */
    public static final Object[][] COL_MISCARE = {
        {"M_Warehouse_ID", REF_INTEGER, 0, "W"},
        {"EVA_TipMiscareWms", REF_STRING, 20, "tipul mișcării (TipMiscareWms)"},
        {"M_Product_ID", REF_INTEGER, 0, "ce se mișcă"},
        {"M_AttributeSetInstance_ID", REF_INTEGER, 0, "lotul"},
        {"PP_Product_BOM_ID", REF_INTEGER, 0, "versiunea listei de materiale a setului (0 pe piese)"},
        {"Qty", REF_NUMBER, 0, "cantitatea, > 0"},
        {"M_Locator_ID", REF_INTEGER, 0, "de unde (gol la intrare)"},
        {"M_LocatorTo_ID", REF_INTEGER, 0, "unde (gol la ieșire)"},
        {"AD_Table_ID", REF_INTEGER, 0, "tabela documentului-sursă"},
        {"Record_ID", REF_INTEGER, 0, "documentul-sursă"},
        {"EVA_LinieSursa_ID", REF_INTEGER, 0, "linia documentului-sursă"},
        {"C_Order_ID", REF_INTEGER, 0, "comanda (CULEGERE, LIVRARE)"},
        {"EVA_FaraCulegere", REF_YESNO, 1, "ieșire contabilă fără culegere"},
        {"EVA_CantitateLipsa", REF_NUMBER, 0, "partea neacoperită din W"},
        {"EVA_MiscareWmsInversa_ID", REF_INTEGER, 0, "pe STORNARE: mișcarea inversată"},
    };

    /** {tabela, nume afișat, descriere, coloanele}. */
    public static final Object[][] TABELE = {
        {PERECHE, "EvA — Perechea WMS a gestiunii", "Legătura una la una gestiune contabilă G ↔ gestiune WMS W, cu cele 3 zone", COL_PERECHE},
        {STOC, "EvA — Stocul validat WMS", "Cantitatea validată pe W × locator × produs × lot × versiunea setului", COL_STOC},
        {MISCARE, "EvA — Mișcările WMS", "Jurnalul mișcărilor stocului validat (doar adăugare)", COL_MISCARE},
    };

    /** Indexurile: {nume, DDL idempotent}; unicitatea F-2 (una la una) și cheia F-4. */
    public static final String[][] INDEXURI = {
        {"eva_perechewms_g_uk", "CREATE UNIQUE INDEX IF NOT EXISTS eva_perechewms_g_uk ON eva_perechewms (ad_client_id, m_warehouse_id)"},
        {"eva_perechewms_w_uk", "CREATE UNIQUE INDEX IF NOT EXISTS eva_perechewms_w_uk ON eva_perechewms (ad_client_id, eva_gestiunewms_id)"},
        {"eva_stocwms_uk", "CREATE UNIQUE INDEX IF NOT EXISTS eva_stocwms_uk ON eva_stocwms"
            + " (ad_client_id, m_locator_id, m_product_id, m_attributesetinstance_id, pp_product_bom_id)"},
        {"eva_miscarewms_sursa_ix", "CREATE INDEX IF NOT EXISTS eva_miscarewms_sursa_ix ON eva_miscarewms (ad_client_id, ad_table_id, record_id)"},
    };

    /**
     * Creează / completează cele 3 tabele și indexurile; întoarce câte obiecte de dicționar a creat (0 = totul exista). Un index
     * care nu se poate crea ⇒ {@link AdempiereException} cu numele și mesajul lui (nu se înghite; apelantul îl scrie în jurnalul pornirii).
     */
    public static int ensureTables(Properties ctx) {
        int create = 0;
        for (Object[] t : TABELE)
            create += com.eva.ro.contab.setup.EvaMetadata.ensureTabelaSpecT331(ctx, (String) t[0], (String) t[1], (String) t[2],
                    (Object[][]) t[3]);
        if (create > 0)
            CacheMgt.get().reset();
        List<String> esuate = com.eva.ro.contab.monografie.MonografieTabele.protejeaza(INDEXURI);
        if (!esuate.isEmpty())
            throw new AdempiereException(String.join(" | ", esuate));
        return create;
    }
}
