/**
 * A83 — procesele pe care driverele rundelor de test le-au rulat prin REST și pe care ecranele le cheamă acum
 * din butoane, cu ACEIAȘI parametri (fără ZK, deci testabil): calculul salariilor pe lună
 * ({@code EVA_CalculSalariiRO}), reînchiderea ca operație unică ({@code EVA_InchidereVenituri Reinchide=Y}),
 * restaurarea notelor suspendate ({@code EVA_RestaureazaNoteSuspendate}), înscrierea deconturilor depuse
 * ({@code EVA_InscrieDeconturiDepuse}) și importul cursurilor BNR pe an ({@code EVA_ImportCursuriBNR}).
 *
 * <p>Ecranul nu dublează logica procesului: construiește parametrii (aici) și rulează procesul nativ prin
 * {@link MProcess#processIt} — sincron ({@link #ruleaza}) sau, pentru operațiile lungi (reînchiderea unui lanț
 * de luni a durat în runde până la ore; Cloudflare taie cererea ZK), ca job în fundal prin
 * {@code JobFundal.pornesteProces} (A79 lot 4, 4b: un singur mecanism de fundal).
 */
public final class ProceseEcran {

    private ProceseEcran() {
    }

    public static final String CALCUL_SALARII = "EVA_CalculSalariiRO";
    public static final String INCHIDERE_VENITURI = "EVA_InchidereVenituri";
    public static final String RESTAURARE_NOTE = "EVA_RestaureazaNoteSuspendate";
    public static final String INSCRIERE_DEPUSE = "EVA_InscrieDeconturiDepuse";
    public static final String CURSURI_BNR = "EVA_ImportCursuriBNR";
    /** T03-05/06: nota statului de salarii (Validez din «State salarii»), aceeași ca operația SAL a închiderii. */
    public static final String INREGISTRARE_SALARII = "EVA_InregistrareSalarii";
    /** T03-28 (A86 C19): «Control reevaluare valutară» — proces DOAR CITIRE (EvaMetadata, parametrii LunaDeLa/LunaPanaLa). */
    public static final String CONTROL_REEVALUARE = "EVA_ControlReevaluareValutara";

    /** Operațiile reînchiderii implicite — exact ce ia {@code ReinchidereLant.plan} când «Operatie» lipsește. */
    public static final String OPERATII_REINCHIDERE_IMPLICITE = "REZ,VC,IMP,CURS";

    // ───────────────────────────────────────────── parametrii (aceiași ca în drivere)

    /**
     * «Calculează luna» = {@code eva_calculsalariiro {"Luna", "DoarVerifica":"N"}} (driverul {@code decl.py}); cu
     * «Forțează» = {@code {"Forteaza":"Y"}} ({@code reinchide.py}) — recalculul unei singure luni peste poarta de
     * ordine N119. {@code DoarVerifica=N} e obligatoriu: fără el procesul rulează ca sandbox și șterge statul.
     */
    public static ProcessInfoParameter[] calculSalarii(String luna, boolean forteaza) {
        List<ProcessInfoParameter> p = new ArrayList<>();
        p.add(new ProcessInfoParameter("Luna", luna, null, null, null));
        p.add(new ProcessInfoParameter("DoarVerifica", "N", null, null, null));
        p.add(new ProcessInfoParameter("Forteaza", forteaza ? "Y" : "N", null, null, null));
        return p.toArray(new ProcessInfoParameter[0]);
    }

    /**
     * Reînchiderea lanțului {@code de…pana} ({@code reinchide_lant.py}): {@code DateFrom} = prima zi a primei luni,
     * {@code DateTo} = ultima zi a ultimei luni, {@code Reinchide=Y}, {@code Operatie} (gol = implicit
     * {@value #OPERATII_REINCHIDERE_IMPLICITE}) și {@code Extra} (sub-intervale «OP,OP@AAAA-LL..AAAA-LL[!stat]»).
     */
    public static ProcessInfoParameter[] reinchidere(YearMonth de, YearMonth pana, String operatii, String extra) {
        List<ProcessInfoParameter> p = new ArrayList<>();
        p.add(new ProcessInfoParameter("DateFrom", Timestamp.valueOf(de.atDay(1).atStartOfDay()), null, null, null));
        p.add(new ProcessInfoParameter("DateTo", Timestamp.valueOf(pana.atEndOfMonth().atStartOfDay()), null, null,
                null));
        p.add(new ProcessInfoParameter("Reinchide", "Y", null, null, null));
        if (operatii != null && !operatii.isBlank())
            p.add(new ProcessInfoParameter("Operatie", operatii.trim(), null, null, null));
        if (extra != null && !extra.isBlank())
            p.add(new ProcessInfoParameter("Extra", extra.trim(), null, null, null));
        return p.toArray(new ProcessInfoParameter[0]);
    }

    /** Lista operațiilor bifate, în ordinea reînchiderii (REZ, VC, IMP, CURS, SAL, AMORT); gol = niciuna. */
    public static String operatii(boolean rez, boolean vc, boolean imp, boolean curs, boolean sal, boolean amort) {
        List<String> o = new ArrayList<>();
        if (rez) o.add("REZ");
        if (vc) o.add("VC");
        if (imp) o.add("IMP");
        if (curs) o.add("CURS");
        if (sal) o.add("SAL");
        if (amort) o.add("AMORT");
        return String.join(",", o);
    }

    /** «Înscrie deconturi depuse» ({@code lant.sh}): {@code Dosar} + opțional {@code Index} și {@code Firma}. */
    public static ProcessInfoParameter[] inscriereDepuse(String dosar, String index, String firma) {
        List<ProcessInfoParameter> p = new ArrayList<>();
        p.add(new ProcessInfoParameter("Dosar", dosar, null, null, null));
        if (index != null && !index.isBlank())
            p.add(new ProcessInfoParameter("Index", index, null, null, null));
        if (firma != null && !firma.isBlank())
            p.add(new ProcessInfoParameter("Firma", firma, null, null, null));
        return p.toArray(new ProcessInfoParameter[0]);
    }

    /**
     * T03-05/06: «Validez» statul lunii = {@code EVA_InregistrareSalarii {DateTo = ultima zi a lunii,
     * EvaVerificOrdinea = Y}} — aceiași parametri ca ecranul «State salarii» (ordinea lunilor verificată de proces).
     */
    public static ProcessInfoParameter[] inregistrareSalarii(String luna) {
        YearMonth l = YearMonth.parse(luna);
        return new ProcessInfoParameter[]{
            new ProcessInfoParameter("DateTo", Timestamp.valueOf(l.atEndOfMonth().atStartOfDay()), null, null, null),
            new ProcessInfoParameter(com.eva.ro.contab.fiscal.InchidereLuna.PARAM_ORDINE, "Y", null, null, null)};
    }

    /** T03-28: «Control reevaluare valutară» pe intervalul de luni {@code yyyy-MM} (gol = parametru lipsă). */
    public static ProcessInfoParameter[] controlReevaluare(String deLa, String panaLa) {
        List<ProcessInfoParameter> p = new ArrayList<>();
        if (deLa != null && !deLa.isBlank())
            p.add(new ProcessInfoParameter("LunaDeLa", deLa.trim(), null, null, null));
        if (panaLa != null && !panaLa.isBlank())
            p.add(new ProcessInfoParameter("LunaPanaLa", panaLa.trim(), null, null, null));
        return p.toArray(new ProcessInfoParameter[0]);
    }

    /** Cursurile BNR ale unui an întreg ({@code eva_importcursuribnr {"An":AN}}); {@code an <= 0} = ultimele 10 zile. */
    public static ProcessInfoParameter[] cursuriBnr(int an) {
        return an > 0 ? new ProcessInfoParameter[]{new ProcessInfoParameter("An", Integer.valueOf(an), null, null,
                null)} : new ProcessInfoParameter[0];
    }

    // ───────────────────────────────────────────── rularea

    /** Rezultatul unei rulări: reușita, rezumatul procesului și jurnalul lui (addLog). */
    public static final class Rezultat {
        public final boolean ok;
        public final String sumar;
        public final List<String> jurnal;

        public Rezultat(boolean ok, String sumar, List<String> jurnal) {
            this.ok = ok;
            this.sumar = sumar == null ? "" : sumar;
            this.jurnal = jurnal == null ? List.of() : jurnal;
        }

        /** Rezumatul + jurnalul, pe rânduri (pentru fereastra de rezultat). */
        public String text() {
            StringBuilder sb = new StringBuilder(sumar);
            for (String l : jurnal)
                sb.append('\n').append(l);
            return sb.toString();
        }
    }

    /**
     * Rulează SINCRON procesul nativ {@code valoare}, în tranzacția lui (commit doar la reușită); orice eroare
     * devine un rezultat cu mesaj, nu o excepție tăcută.
     */
    public static Rezultat ruleaza(Properties ctx, String valoare, String titlu, ProcessInfoParameter[] parametri) {
        return ruleazaIntern(ctx, valoare, titlu, parametri);
    }

    /**
     * P01.T58 L5 (A-10 (4), CO-6): ca {@link #ruleaza(Properties, String, String, ProcessInfoParameter[])}, cu marcajul
     * confirmării duble ({@link com.eva.ro.contab.fiscal.AlarmaLunaViitoare.Marcaj}) pus pe firul care execută
     * {@code processIt} și scos în {@code finally} — NU un parametru de proces (un apel REST nu-l poate falsifica).
     */
    public static Rezultat ruleaza(Properties ctx, String valoare, String titlu, ProcessInfoParameter[] parametri,
            com.eva.ro.contab.fiscal.AlarmaLunaViitoare.Marcaj marcaj) {
        com.eva.ro.contab.fiscal.AlarmaLunaViitoare.pune(marcaj);
        try {
            return ruleazaIntern(ctx, valoare, titlu, parametri);
        } finally {
            com.eva.ro.contab.fiscal.AlarmaLunaViitoare.scoate(marcaj);
        }
    }

