/**
 * T41 L5L6 r3 (01b_decizii_dupa_aud1_L5L6_r1 D-A1L56-2, P-1 al aud1 r1) și T41 L3L4 r2 (01b D-A2L34-4, AM-1: același tipar, copiat din
 * L5L6 — pe master întâi prin L3L4, tabelele dosarului L2 / L4 în {@link MonoRoluri#tabeleDoarProcese}) — rolul creat (sau re-activat)
 * DUPĂ pornire primește IMEDIAT regula REST «doar citire» ({@link MonoRoluri#regleazaTabeleRest}, aceeași ca la pornire), nu abia la
 * pornirea următoare: {@code PO_AFTER_NEW} / {@code PO_AFTER_CHANGE} pe {@code AD_Role}, în TRANZACȚIA salvării rolului (fereastra
 * nativă «Role», REST {@code /api/v1/models/ad_role}, «Initial Client Setup»). Decizia = {@link MonoRoluri#reguliLaSalvareRol} (pură).
 * O eroare (tabelă lipsă, firma rolului nedeterminată) NU se înghite: {@code AbstractEventHandler.handleEvent} o adaugă la eveniment și
 * o re-aruncă ⇒ salvarea rolului eșuează (eșec ÎNCHIS, bytecode iDempiere 13 în {@code dovezi-03-L5L6-be/r3/}). Nu atinge nicio
 * postare / document (doar {@code AD_Table_Access}). Înregistrat în {@code EvaActivator}.
 */
public class EvaMonoRoluriEvents extends AbstractEventHandler {

    @Override
    protected void initialize() {
        registerTableEvent(IEventTopics.PO_AFTER_NEW, MRole.Table_Name);
        registerTableEvent(IEventTopics.PO_AFTER_CHANGE, MRole.Table_Name);
    }

    @Override
    protected void doHandleEvent(Event event) {
        PO po = getPO(event);
        boolean nou = IEventTopics.PO_AFTER_NEW.equals(event.getTopic());
        if (MonoRoluri.reguliLaSalvareRol(nou, po.getAD_Client_ID(), po.isActive(), po.is_ValueChanged("IsActive")))
            MonoRoluri.regleazaTabeleRest(po.getCtx(), po.get_ID(), po.get_TrxName());
    }
}
package com.eva.ro.contab.component;

import org.adempiere.base.event.AbstractEventHandler;
import org.adempiere.base.event.IEventTopics;
import org.compiere.model.PO;
import org.osgi.service.event.Event;

import com.eva.ro.contab.corelare.CanalB2B;

/**
 * P01.T316 (P01.C10.T0017) A-4 / A-5 (spec {@code 04_} §3.4 pașii 6–7, D-316-9) — handlerul UNIC al comenzii de vânzare intrate pe un
 * canal B2B, oricare ar fi drumul (K12, fereastra nativă, REST / PO, generatorul site-ului): lista, termenul și campania canalului pe
 * antet, prețul listei antetului pe linii, lista comenzii pe factura ei, limita de credit la «Validez». Regulile și lipiciul stau în
 * {@link CanalB2B}; aici doar înregistrarea și dispecerizarea pe tabelă. Înregistrat programatic în {@code EvaActivator} (blocul
 * {@code // P01.T316}).
 */
public class EvaCanalB2BEvents extends AbstractEventHandler {

    /** Evenimentele înregistrate, pe tabelă: {tabela, topic} (testul de legătură citește lista, M-05). */
    public static final String[][] EVENIMENTE = {
        {"C_Order", IEventTopics.PO_BEFORE_NEW},
        {"C_Order", IEventTopics.PO_BEFORE_CHANGE},
        {"C_Order", IEventTopics.DOC_BEFORE_PREPARE},
        {"C_OrderLine", IEventTopics.PO_BEFORE_NEW},
        {"C_OrderLine", IEventTopics.PO_BEFORE_CHANGE},
        {"C_Invoice", IEventTopics.PO_BEFORE_NEW},
    };

    @Override
    protected void initialize() {
        for (String[] e : EVENIMENTE)
            registerTableEvent(e[1], e[0]);
    }

    @Override
    protected void doHandleEvent(Event event) {
        PO po = getPO(event);
        String eroare = dispecer(event.getTopic(), po == null ? null : po.get_TableName(), po, CanalB2B.BAZA);
        if (eroare != null)
            addErrorMessage(event, eroare);
    }

    /** Dispecerul pe tabelă (static, testat): comanda / linia / factura, cu sursele date; altă tabelă ⇒ nimic. */
    public static String dispecer(String topic, String tabela, PO po, CanalB2B.Surse s) {
        if ("C_Order".equalsIgnoreCase(tabela))
            return CanalB2B.comandaB2B(topic, po, s);
        if ("C_OrderLine".equalsIgnoreCase(tabela))
            return CanalB2B.linieB2B(topic, po, s);
        if ("C_Invoice".equalsIgnoreCase(tabela))
            return CanalB2B.facturaB2B(topic, po, s);
        return null;
    }
}

