    private static final ThreadLocal<RulareAutomata> RULARE = new ThreadLocal<>();

    /** Contextul firului curent (null = nu e rulare automată). */
    public static RulareAutomata rulareCurenta() {
        return RULARE.get();
    }

    /** beforeProcess(ClientAcctProcessor): contextul pe fir (firma ≤ 0 ⇒ fără context: căile rămân la G1, refuz explicit — E4). */
    public static void incepeRulare(int client) {
        if (client > 0)
            RULARE.set(new RulareAutomata(client));
        else
            RULARE.remove();
    }

    /** postProcess(ClientAcctProcessor), pe ambele ramuri (N-21): un rând agregat dacă s-au amânat documente, apoi contextul se curăță. */
    public static void inchideRulare(Efecte e) {
        RulareAutomata r = RULARE.get();
        if (r == null)
            return;
        RULARE.remove();
        if (r.excluse > 0)
            e.audit(r.client, 0, 0, JurnalAudit.OK, A_EXCLUSE, r.excluse);
    }

