    /** Înregistrările exacte ale gărzii (T23, T37). */
    public static void inregistreaza(Registru r) {
        r.eveniment(IEventTopics.DOC_BEFORE_POST);
        for (int t : GardaRepostareImport.TABELE_G2) {
            String nume = NUME_G2.get(t);
            if (nume == null)
                throw new IllegalStateException(String.valueOf(t));
            r.tabela(IEventTopics.DOC_BEFORE_REACTIVATE, nume);
        }
        r.proces(IEventTopics.BEFORE_PROCESS, FACT_ACCT_RESET);
        r.proces(IEventTopics.BEFORE_PROCESS, CLIENT_ACCT);
        r.proces(IEventTopics.POST_PROCESS, CLIENT_ACCT);
        r.tabela(IEventTopics.PO_BEFORE_NEW, MSysConfig.Table_Name);
        r.tabela(IEventTopics.PO_BEFORE_CHANGE, MSysConfig.Table_Name);
        r.tabela(IEventTopics.PO_BEFORE_DELETE, MSysConfig.Table_Name);
        r.tabela(IEventTopics.PO_BEFORE_NEW, MAcctProcessor.Table_Name);
        r.tabela(IEventTopics.PO_BEFORE_CHANGE, MAcctProcessor.Table_Name);
    }

