     * apelantului (procesul). Un refuz al regulii ⇒ {@link Rezultat} cu textul tradus și nimic scris; o eroare tehnică urcă.
     */
    public static Rezultat activeaza(Properties ctx, int client, int whContabil, String trx) {
        client(client);
        String tipG = null;
        boolean gasita = false;
        try (PreparedStatement ps = DB.prepareStatement(SQL_G_BLOCAT, trx)) {
            DB.setParameters(ps, new Object[] {client, whContabil});
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    gasita = true;
                    String t = rs.getString(2);
                    tipG = t == null || t.isBlank() ? TipGestiune.CV : t.strip();
                }
            }
        } catch (SQLException e) {
            throw new DBException(e, SQL_G_BLOCAT);
        }
        if (!gasita)
            return new Rezultat(null, false, 0, textRefuz(R_TIP, String.valueOf(whContabil), List.of()));
        MWarehouse g = new MWarehouse(ctx, whContabil, trx);
        PerecheWms existenta = dupaContabila(client, whContabil, trx);
        List<StocInitial> stoc = stocG(client, whContabil, trx);
        List<String> neg = negative(stoc);
        String refuz = refuzPereche(tipG, !neg.isEmpty(), existenta != null, EvaGestiuni.eTehnica(g));
        if (R_DEJA.equals(refuz))
            return new Rezultat(existenta, false, 0, null);
        if (refuz != null)
            return new Rezultat(null, false, 0, textRefuz(refuz, g.getName(), neg));
        LocalDate azi = LocalDate.now(OraRO.ZONA);
        String sufix = setare(client, SetariFirmaPerioadaCatalog.CHEIE_WMS_SUFIX_COD, azi);
        String codW = g.getValue() + sufix, numeW = g.getName() + sufix;
        String codRec = setare(client, SetariFirmaPerioadaCatalog.CHEIE_WMS_COD_RECEPTIE, azi);
        String codExp = setare(client, SetariFirmaPerioadaCatalog.CHEIE_WMS_COD_EXPEDIERE, azi);
        String codNea = setare(client, SetariFirmaPerioadaCatalog.CHEIE_WMS_COD_NEAMPLASAT, azi);
        POInfo infoW = POInfo.getPOInfo(ctx, MWarehouse.Table_ID, trx), infoL = POInfo.getPOInfo(ctx, MLocator.Table_ID, trx);
        Camp lung = primaPreaLunga(campuriActivare(codW, numeW, List.of(codRec, codExp, codNea), infoW.getFieldLength("Value"),
                infoW.getFieldLength("Name"), infoL.getFieldLength("Value"), infoL.getFieldLength("X")));
        if (lung != null)
            return new Rezultat(null, false, 0, textLungime(lung));
        MWarehouse w = new MWarehouse(ctx, 0, trx);
        w.setAD_Org_ID(g.getAD_Org_ID());
        w.setValue(codW);
        w.setName(numeW);
        w.setC_Location_ID(g.getC_Location_ID());
        w.set_ValueOfColumn(TipGestiune.COL_TIP, TipGestiune.NC);
        JETON_ACTIVARE.set(Boolean.TRUE);
        try {
            w.saveEx();
        } finally {
            JETON_ACTIVARE.remove();
        }
        int receptie = zona(w, codRec, false);
        int expediere = zona(w, codExp, false);
        int neamplasat = zona(w, codNea, true);
        RegistruWms.tipDocument(ctx, client, trx);
        List<MiscareWms> act = miscariActivare(stoc, w.getM_Warehouse_ID(), neamplasat, MTable.getTable_ID(MWarehouse.Table_Name),
                whContabil);
        StocWms.inregistreaza(ctx, client, act, trx);
        Timestamp acum = new Timestamp(System.currentTimeMillis());
        PO r = MTable.get(ctx, ModelWms.PERECHE).getPO(0, trx);
        r.setAD_Org_ID(g.getAD_Org_ID());
        r.set_ValueOfColumn("M_Warehouse_ID", whContabil);
        r.set_ValueOfColumn("EVA_GestiuneWms_ID", w.getM_Warehouse_ID());
        r.set_ValueOfColumn("EVA_LocatorReceptie_ID", receptie);
        r.set_ValueOfColumn("EVA_LocatorExpediere_ID", expediere);
        r.set_ValueOfColumn("EVA_LocatorNeamplasat_ID", neamplasat);
        r.set_ValueOfColumn("EVA_DataActivare", acum);
        JETON_ACTIVARE.set(Boolean.TRUE);
        try {
            r.saveEx();
        } catch (RuntimeException e) {
            String cheie = dinIndex(e);
            throw new AdempiereException(textRefuz(cheie, R_W_LEGATA.equals(cheie) ? w.getName() : g.getName(), List.of()), e);
        } finally {
            JETON_ACTIVARE.remove();
        }
        return new Rezultat(new PerecheWms(client, whContabil, w.getM_Warehouse_ID(), receptie, expediere, neamplasat, acum), true,
                act.size(), null);
    }

