    private interface Lucru<T> {
        T run(String trx);
    }

    /**
     * {@code trxName == null} → tranzacție proprie, commit la final, {@link #dupaCommit()}, rollback la orice excepție;
     * altfel lucrează în ea, fără commit (apelantul cheamă dupaCommit după commit). Primul pas: lacătul pe firmă.
     */
    private static <T> T inTrx(int client, String trxName, Lucru<T> f) {
        if (trxName != null) {
            depozit.blocheaza(client, trxName);
            return f.run(trxName);
        }
        if (!(depozit instanceof DepozitBd)) {
            String t = "mem-" + client;
            depozit.blocheaza(client, t);
            T r = f.run(t);
            dupaCommit();
            return r;
        }
        Trx trx = Trx.get(Trx.createTrxName("EvaSetFirma"), true);
        try {
            depozit.blocheaza(client, trx.getTrxName());
            T r = f.run(trx.getTrxName());
            trx.commit(true);
            dupaCommit();
            return r;
        } catch (RuntimeException e) {
            trx.rollback();
            throw e;
        } catch (java.sql.SQLException e) {
            trx.rollback();
            throw new AdempiereException(e.getMessage(), e);
        } finally {
            trx.close();
        }
    }

