    /** Stocul transmis = max(0, ⌊Σ gestiuni − rezervări − comenzi nelivrate − rezervă⌋); {@code reguliCanal} gol = fără reguli. */
    public static long stocCalculat(java.util.List<java.math.BigDecimal> stocuriGestiuni, java.math.BigDecimal rezervari,
            java.math.BigDecimal comenziNelivrate, long rezerva, java.util.Map<String, String> reguliCanal) {
        BigDecimal suma = BigDecimal.ZERO;
        if (stocuriGestiuni != null)
            for (BigDecimal s : stocuriGestiuni)
                if (s != null)
                    suma = suma.add(s);
        BigDecimal disponibil = suma.subtract(rezervari == null ? BigDecimal.ZERO : rezervari)
                .subtract(comenziNelivrate == null ? BigDecimal.ZERO : comenziNelivrate).subtract(BigDecimal.valueOf(Math.max(0L, rezerva)));
        long stoc = Math.max(0L, disponibil.setScale(0, RoundingMode.FLOOR).longValue());
        stoc = RegulaStocCanal.cantitateOferita(stoc, reguliCanal);   // T35 L3 (M-6): cantitatea oferită pe canal
        return stoc;
