    /** Cârligul testului (X216): vizibil doar în pachet, implicit {@code null}, nicio atribuire în {@code src}. */
    static Citiri dublaCitiri = null;

    static Citiri citiri() {
        return dublaCitiri != null ? dublaCitiri : BAZA;
    }

    /** Firma curentă; nedeterminată (≤ 0) ⇒ refuz (eșec închis, X18 / X207). */
    static int firma(int client) {
        if (client <= 0)
            throw new Refuz(K_FIRMA);
        return client;
    }

    /** Articolul din rândul {@link #SQL_PRODUS} (pur pe {@code ResultSet}). */
    static Object[] produsDin(ResultSet rs) throws SQLException {
        return rs.next() ? new Object[]{"Y".equals(rs.getString(1)), "Y".equals(rs.getString(2)), rs.getString(3)} : null;
    }

    /** Id-urile listelor din {@link #SQL_LISTE} (pur pe {@code ResultSet}). */
    static List<Integer> listeDin(ResultSet rs) throws SQLException {
        List<Integer> l = new ArrayList<>();
        while (rs.next())
            l.add(rs.getInt(1));
        return l;
    }

    /** Rândurile din {@link #SQL_RANDURI} (pur pe {@code ResultSet}; fiecare coloană pe poziția ei). */
    static List<RandLista> randuriDin(ResultSet rs) throws SQLException {
        List<RandLista> l = new ArrayList<>();
        while (rs.next())
            l.add(new RandLista(rs.getInt(1), rs.getBigDecimal(2), rs.getString(3), "Y".equals(rs.getString(4)), rs.getBigDecimal(5),
                    rs.getBoolean(6), rs.getBoolean(7), rs.getBoolean(8)));
        return l;
    }

    /** Parametrii {@link #SQL_CERERE_COMPONENTA} în ordine (pur): filtrul consumatorului devine cele două comutatoare. */
    static Object[] parametriCerere(int client, int componenta, FiltruCerere f, int exclus) {
        boolean rez = f == FiltruCerere.REZERVATE_ALTE_COMENZI;
        return new Object[]{PREFIX_MOTOR, client, componenta, exclus, rez, DomeniiT22.REZERVAT, !rez, DomeniiT22.EXCLUS};
    }

    interface Cititor<T> {
        T citeste(ResultSet rs) throws SQLException;
    }

    static <T> T interogare(String sql, String trx, Cititor<T> c, Object... p) {
        try (PreparedStatement ps = org.compiere.util.DB.prepareStatement(sql, trx)) {
            for (int i = 0; i < p.length; i++)
                ps.setObject(i + 1, p[i]);
            try (ResultSet rs = ps.executeQuery()) {
                return c.citeste(rs);
            }
        } catch (SQLException e) {
            throw new IllegalStateException(e.getMessage(), e);
        }
    }

    static final Citiri BAZA = new Citiri() {
        @Override
        public Object[] produs(int client, int produs, String trx) {
            return interogare(SQL_PRODUS, trx, SetLista::produsDin, client, produs);
        }

        @Override
        public List<Integer> liste(int client, int produs, String trx) {
            return interogare(SQL_LISTE, trx, SetLista::listeDin, client, produs, PREFIX_MOTOR);
        }

        @Override
        public List<RandLista> randuri(int client, int lista, String trx) {
            return interogare(SQL_RANDURI, trx, SetLista::randuriDin, client, lista);
        }

        @Override
        public BigDecimal cerere(int client, int componenta, FiltruCerere f, int exclus, String trx) {
            return interogare(SQL_CERERE_COMPONENTA, trx, rs -> rs.next() && rs.getBigDecimal(1) != null ? rs.getBigDecimal(1) : BigDecimal.ZERO,
                    parametriCerere(client, componenta, f, exclus));
        }
    };

