        o.saveEx();
        Map<Integer, MOrderLine> peLinie = new LinkedHashMap<>();
        Map<Integer, List<MOrderLine>> liniiComanda = new LinkedHashMap<>();   // P01.T203 D-33: tipul 3 = o linie pe serie
        Map<Integer, MOrderLine> peIdComanda = new LinkedHashMap<>();
            // 74o D-B2: c.transport() = transportul FACTURAT (TarifTransport.calculeaza; null / 0 = «apare pe factură» Nu ⇒ 0 linii);
            // net = brut / (1 + cota articolului «Transport»)
            if (c.transport() != null && c.transport().signum() != 0)
                servicii.add(linieServiciu(o, nr += 10, s.articolTransport(), BigDecimal.ONE, c.transport(),
                        cotaArticol(s.articolTransport(), cotaServ, dataFact, trx), client, dataFact));
            if (c.discount() != null && c.discount().signum() != 0) {
                Map<Integer, BigDecimal> brutPeCota = new LinkedHashMap<>();
                for (Linie l : val)
                    brutPeCota.merge(l.cotaLegala(), l.pretBrutLei().multiply(l.cantitate()), BigDecimal::add);
                for (Map.Entry<Integer, BigDecimal> e : repartizeazaDiscount(brutPeCota, c.discount()).entrySet())
                    servicii.add(linieServiciu(o, nr += 10, s.articolDiscount(), BigDecimal.ONE, e.getValue().negate(), e.getKey(), client, dataFact));
            }
        }
        try (AutoCloseable gen = SetLista.emitere(trx, MOrder.Table_Name, o.getC_Order_ID())) {   // P01.T354 (D-ORC-6): documentul generatorului
            if (!o.processIt(DocAction.ACTION_Complete))
                throw new IllegalStateException(Etichete.t("vanzari.doc.refuz_nativ", "C_Order", o.getProcessMsg()));
        }
        o.saveEx();
        // 4. livrarea din comandă, pe locațiile cu stoc (nicio locație negativă)
        MInOut io = new MInOut(o, s.docLivrare(), dataFact);
        if (c.descriereLivrare() != null)
            io.addDescription(c.descriereLivrare());
        // P01.T337 — început (A-2 pas 2, D-T337-4): combinațiile tipului EFECTIV al livrării, înaintea primei scrieri a livrării (0 documente)
        boolean[] tip337 = Culegere.steaguriTip(io.getC_DocType_ID(), client, trx);
        String rc337 = Culegere.refuzCombinatie(tip337[0], tip337[1], tip337[2]);
        if (rc337 != null)
            throw new Refuz(Etichete.t(rc337, io.getDocStatus()), liniiStocabile(val));
        // P01.T337 — sfârșit
        io.saveEx();
        Map<String, BigDecimal> sumaVal = new LinkedHashMap<>();
        Map<Integer, List<MInOutLine>> liniiLivrare = new LinkedHashMap<>();
        com.eva.ro.contab.culegere.OrdineCulegere.PeVal culegere = com.eva.ro.contab.culegere.OrdineCulegere.PeVal.dinBaza(client, trx);   // # P01.T326
        for (Linie l : val) {
            if (l.esteSet())   // P01.T354 A (R6): seturile se livrează după liniile directe (livreazaSeturi), pe stocul rămas
                continue;
            if (!l.stocabil())
                continue;
            if (liniePeSerie(l.tipSerie())) {
                // P01.T203 D-33: tipul 3 — linia livrării pe linia comenzii a seriei, instanța aleasă, locația care o ține
                for (MOrderLine ol : liniiComanda.get(l.idLinie())) {
                    int asi = ol.getM_AttributeSetInstance_ID();
                    int locator = DB.getSQLValueEx(trx, SQL_LOCATIE_INSTANTA, client, s.gestiune(), l.produs(), asi);
                    if (locator <= 0)
                        throw new Refuz(Etichete.t("conformitate.serii.fara_stoc", DB.getSQLValueStringEx(trx,
                                "SELECT serno FROM m_attributesetinstance WHERE ad_client_id=? AND m_attributesetinstance_id=?", client, asi),
                                org.compiere.model.MProduct.get(ctx, l.produs()).getValue()), liniiProdus(val, l.produs()));
                    MInOutLine il = new MInOutLine(io);
                    il.setOrderLine(ol, locator, BigDecimal.ONE);
                    il.setM_AttributeSetInstance_ID(asi);
                    il.setQty(BigDecimal.ONE);
                    il.saveEx();
                    liniiLivrare.computeIfAbsent(l.idLinie(), x -> new ArrayList<>()).add(il);
                }
                sumaVal.merge(RezervareStoc.cheie(l.produs(), s.gestiune()), l.cantitate(), BigDecimal::add);
                continue;
            }
            Map<Integer, BigDecimal> loc = peLocatii(l.cantitate(), stocPeLocatii(client, l.produs(), s.gestiune(), trx));
            loc = culegere.loc(l.produs(), l.cantitate(), loc, () -> stocPeLocatii(client, l.produs(), s.gestiune(), trx));   // # P01.T326
            if (loc == null)
                throw new Refuz(Etichete.t("vanzari.stoc.negativ_interzis", l.idLinie()), liniiProdus(val, l.produs()));
            List<Plasare> plasari = plaseaza(bucatiLinie.get(l.idLinie()), loc);
            if (plasari == null)
                throw new Refuz(Etichete.t("vanzari.validare.serii_invalide"), liniiProdus(val, l.produs()));
            for (Plasare pl : plasari) {
                MInOutLine il = new MInOutLine(io);
                il.setOrderLine(peLinie.get(l.idLinie()), pl.locator(), pl.bucata().cantitate());
                // P01.T203 A-6: tipul 2 — instanța NOUĂ cu seria pe fiecare bucată; stocul fără instanță trece nativ pe ea
                // (MInOut.moveOnHandToShipmentASI, P0-1)
                if (pl.bucata().serie() != null)
                    il.setM_AttributeSetInstance_ID(instantaNoua(ctx, l.produs(), pl.bucata().serie(), trx));
                il.setQty(pl.bucata().cantitate());
                il.saveEx();
                liniiLivrare.computeIfAbsent(l.idLinie(), x -> new ArrayList<>()).add(il);
            }
            sumaVal.merge(RezervareStoc.cheie(l.produs(), s.gestiune()), l.cantitate(), BigDecimal::add);
        }
        livreazaSeturi(io, val, liniiComanda, liniiLivrare, sumaVal, culegere, client, s.gestiune(), trx);   // P01.T354 A (R6)
        // garda (a doua barieră): suma valului pe cheie față de stocul fizic din harta «fizic», citită la pasul 1 sub
        // SELECT … FOR UPDATE — rândurile rămân blocate până la sfârșitul tranzacției, deci valoarea e încă cea curentă (95a F-3)
        for (Map.Entry<String, BigDecimal> e : sumaVal.entrySet()) {
            String[] k = e.getKey().split("\\|");
            int produs = Integer.parseInt(k[0]);
            if (RezervareStoc.lasaNegativ(fizic.get(e.getKey()), e.getValue()))
                throw new Refuz(Etichete.t("vanzari.stoc.negativ_interzis", produs), liniiProdus(val, produs));
        }
        try (AutoCloseable gen = SetLista.emitere(trx, MInOut.Table_Name, io.getM_InOut_ID())) {   // P01.T354 (D-ORC-6)
            if (!io.processIt(DocAction.ACTION_Complete))
                throw new Refuz(Etichete.t("vanzari.doc.refuz_nativ", "M_InOut", io.getProcessMsg()), liniiStocabile(val));
        }
        io.saveEx();
        // P01.T337 — început (A-2 pas 3, F-2 închis pe efect): starea livrării CITITĂ din bază după «Complete»; în culegere ⇒ faza 1
        String stareIo = DB.getSQLValueStringEx(trx, Culegere.SQL_STARE_LIVRARE, io.getM_InOut_ID(), client);
        int pcDeschis = DB.getSQLValueEx(trx, Culegere.SQL_PC_DESCHIS, io.getM_InOut_ID(), client);
        switch (Culegere.dupaComplete(stareIo, pcDeschis > 0)) {
            case REFUZ -> throw new Refuz(Etichete.t(Culegere.K_LIVRARE_NETERMINATA, stareIo), liniiStocabile(val));
            case CULEGERE -> {
                for (Linie l : val)
                    DB.executeUpdateEx(Culegere.SQL_LEGA_FAZA1, new Object[]{o.getC_Order_ID(), io.getM_InOut_ID(), l.idLinie(), client}, trx);
                return new Rezultat(o.getC_Order_ID(), io.getM_InOut_ID(), 0, rosii, null);
            }
            default -> { }
        }
        return facturaSiLegaturi(ctx, c, s, client, o, io, dataFact, pentruFactura(val), peLinie, liniiLivrare, peIdComanda, servicii, rosii, trx);
        // P01.T337 — sfârșit
    }

