    /** Valul: documentele prin {@link GeneratorDocumente}, liniile, antetul (primul val), jurnalul {@code DOCUMENTE_COMANDA}. */
    private String emiteVal(Properties ctx, int client, Antet a, int sursaId, int gestiune, Map<Integer, RandLinie> peId,
            ValidareComanda.Rezultat r, DetaliuComanda d, CursBnrFactura.Curs curs, int cotaLegala, boolean om, int svc,
            ImpliciteLivrare.Implicite ef, BigDecimal transportFacturat) throws Exception {
        String trx = get_TrxName();
        List<GeneratorDocumente.Linie> val = new ArrayList<>();
        for (int idLinie : r.val()) {
            RandLinie x = peId.get(idLinie);
            BigDecimal pret = curs != null && x.pretValuta() != null ? CursBnrFactura.inLei(x.pretValuta(), curs.rata()) : x.pretBrut();
            if (SetLista.esteSet(client, x.produs(), trx)) {   // P01.T354 A (R3 / R4): setul desfăcut pe componente
                try {
                    val.add(linieSet(client, idLinie, x.produs(), x.cant(), pret, cotaLegala, setariSursa(sursaId, gestiune).listaPret(), trx));
                } catch (SetLista.Refuz e) {   // P01.T354 A (CO-R2-1): refuzul exploziei = comanda în coadă cu motivul, 0 documente
                    addLog(Etichete.t(K_T354_VALIDEZ, a.nr(), e.getMessage()));
                    antetStare(a.id(), DomeniiT22.COADA, e.getMessage(), null);
                    return "COADA";
                }
                continue;
            }
            boolean stocabil = DB.getSQLValue(trx, "SELECT count(*) FROM m_product WHERE m_product_id=? AND isstocked='Y' AND producttype='I'",
                    x.produs()) > 0;
            // P01.T203 A-6: tipul de serie și seriile liniei ({@code EVA_Serii}, forma SeriiArticole.valide) trec în linia documentelor
            String tipSerie = stocabil ? SeriiArticole.tip(x.produs(), trx) : null;
            val.add(new GeneratorDocumente.Linie(idLinie, x.produs(), x.cant(), pret, cotaLegala, stocabil, tipSerie,
                    tipSerie == null ? List.of() : SeriiArticole.seriiLinie(tipSerie, x.serii(), x.cant())));
        }
        boolean primul = a.orderId() <= 0 && DB.getSQLValue(trx, "SELECT count(*) FROM eva_comandasitelinie WHERE eva_comandasite_id=?"
                + " AND c_order_id IS NOT NULL", a.id()) == 0;
        GeneratorDocumente.Setari st = setariSursa(sursaId, gestiune);   // P01.T337: extras (spec §3.4 pas 5), folosit și la confirmare
        DetaliuComanda.Client cl = d.client();
        boolean pj = ValidareComanda.CAT_PJ.equals(categorii(client, "TIP_CLIENT_SITE", trx).get(cl.tip));
        GeneratorDocumente.Partener p = new GeneratorDocumente.Partener(pj, cl.cui, pj ? null : GeneratorDocumente.cheiePf(a.sursa(), cl.ref),
                cl.nume, cl.adresa, cl.oras, cl.judet, cl.codPostal, cl.tara);
        // implicitele livrării (canal › platformă › gol) — scrise pe comandă doar dacă sunt goale; în descrierea livrării
        String curier = a.curier() != null ? a.curier() : ef.curier(), punct = a.punct() != null ? a.punct() : ef.punctLivrare();
        GeneratorDocumente.ComandaDeEmis ce = new GeneratorDocumente.ComandaDeEmis(client, a.sursa(), a.nr(),
                a.dataComanda() == null ? LocalDate.now() : a.dataComanda().toLocalDateTime().toLocalDate(), LocalDate.now(), a.moneda(),
                curs == null ? null : curs.rata(), p, val, transportFacturat, a.discount(), a.metoda(), primul,
                ImpliciteLivrare.descriereLivrare(curier, punct), livrarePartiala(client));
        GeneratorDocumente.Rezultat g;
        try {
            g = GeneratorDocumente.emite(ctx, ce, st, trx);
        } catch (GeneratorDocumente.Refuz e) {
            addLog(e.getMessage());
            for (Map.Entry<Integer, String> x : e.rosii.entrySet())
                DB.executeUpdateEx("UPDATE eva_comandasitelinie SET eva_starelinie=?, eva_cantitaterezervata=0, eva_motivlinie=?, updated=now()"
                        + " WHERE eva_comandasitelinie_id=?", new Object[]{DomeniiT22.ROSU, x.getValue(), x.getKey()}, trx);
            antetStare(a.id(), DomeniiT22.COADA, uneste(r.motiveText(), "V18:" + ValidareComanda.STOC_INSUFICIENT), null);
            return "COADA";
        }
        for (Map.Entry<Integer, String> x : g.rosii().entrySet()) {
            DB.executeUpdateEx("UPDATE eva_comandasitelinie SET eva_starelinie=?, eva_cantitaterezervata=0, eva_motivlinie=?, updated=now()"
                    + " WHERE eva_comandasitelinie_id=?", new Object[]{DomeniiT22.ROSU, x.getValue(), x.getKey()}, trx);
            addLog(Etichete.t("vanzari.stoc.negativ_interzis", x.getKey()));
        }
        if (g.avertisment() != null)
            addLog(g.avertisment());
        if (com.eva.ro.contab.culegere.ListaCulegere.deGenerat(g))   // # P01.T326
            addLog(com.eva.ro.contab.culegere.ListaCulegere.genereazaIzolat(ctx, client, getAD_PInstance_ID(), a.id(), a.nr(), g, cumulCulegere(), trx));   // # P01.T326
        // P01.T337 — început (A-4 pas 4, D-T337-2): valul a rămas în faza 1 (livrarea IP, confirmarea de culegere deschisă, fără factură)
        if (g.inCulegere()) {
            antetStare(a.id(), DomeniiT22.IN_CULEGERE, null, null);
            if (primul)
                DB.executeUpdateEx(Culegere.SQL_ANTET_FAZA1, new Object[]{g.inoutId(), g.orderId(), a.id(), client}, trx);
            addLog(Etichete.t("t337.val.in_culegere", a.nr()));
            return Culegere.REZULTAT_IN_CULEGERE;
        }
        // P01.T337 — sfârșit
        if (!g.emis()) {
            antetStare(a.id(), DomeniiT22.COADA, uneste(r.motiveText(), "V18:" + ValidareComanda.STOC_INSUFICIENT), null);
            return "COADA";
        }
        return inchideVal(ctx, client, a, r, g, primul, om, svc, ef);   // P01.T337: coada extrasă (spec §3.4 pas 5), folosită și la confirmare
    }

    // P01.T337 — început (A-4 pas 5): coada valului emis, mutată neschimbat din emiteVal (faza 0 și faza 2)
    private String inchideVal(Properties ctx, int client, Antet a, ValidareComanda.Rezultat r, GeneratorDocumente.Rezultat g, boolean primul,
            boolean om, int svc, ImpliciteLivrare.Implicite ef) throws Exception {
        String trx = get_TrxName();
        List<String> stari = new ArrayList<>();
        for (String x : DB.getSQLValueString(trx, "SELECT string_agg(coalesce(eva_starelinie,''), ',') FROM eva_comandasitelinie WHERE"
                + " eva_comandasite_id=?", a.id()).split(","))
            stari.add(x);
        String stare = stareDupaVal(stari);
        String motive = DomeniiT22.VALIDAT.equals(stare) ? null : uneste(r.motiveText(), g.rosii().isEmpty() ? null : "V18:" + ValidareComanda.STOC_INSUFICIENT);
        if (primul)
            DB.executeUpdateEx("UPDATE eva_comandasite SET c_order_id=?, m_inout_id=?, c_invoice_id=?, eva_starelegare=?, eva_regula=?,"
                    + " eva_staretrimitere=?, eva_curier=coalesce(eva_curier,?), eva_punctlivrare=coalesce(eva_punctlivrare,?),"
                    + " eva_costtransport=coalesce(eva_costtransport,?), updated=now() WHERE eva_comandasite_id=?",
                    new Object[]{g.orderId(), g.inoutId(), g.invoiceId(), CorelareTabele.LEGAT_AUTO, "T22",
                        STARE_DE_TRIMIS, ef.curier(), ef.punctLivrare(), ef.costTransport(), a.id()}, trx);
        antetStare(a.id(), stare, motive, null);
        // P01.T203 A-7 (D-21): în tranzacția facturii DOAR starea certificatului — AUTOMAT sub serviciu ⇒ DE_EMIS, altfel DE_APROBAT;
        // 0 apeluri RegistruDocumente aici (emiterea = pasul separat după commitEx, sau «Emit»)
        boolean certAuto = DomeniiT22.AUTOMAT.equals(ModOperatie.modCurent(client, DomeniiT22.CERTIFICAT_D1215, trx));
        DB.executeUpdateEx(ConformitateProces.SQL_STARE_LA_FACTURA, new Object[]{ModeleCertificat.stareLaFactura(certAuto,
                svc > 0 && getAD_User_ID() == svc), client, a.id(), ModeleCertificat.STARE_EMIS, ModeleCertificat.STARE_ANULAT,
                ModeleCertificat.STARE_ASTEAPTA}, trx);
        org.compiere.model.MInvoice inv = new org.compiere.model.MInvoice(ctx, g.invoiceId(), trx);
        int tInv = MTable.getTable_ID(org.compiere.model.MInvoice.Table_Name);
        jurnal(ctx, client, DomeniiT22.DOCUMENTE_COMANDA, om ? VALIDEZ : AUTO, svc, tInv, g.invoiceId(), a.nr(), DomeniiT22.VALIDAT,
                r.v07Acceptat() ? Etichete.t("vanzari.validare.v07_acceptat") : null,
                ModOperatie.amprenta(DomeniiT22.DOCUMENTE_COMANDA, tInv, g.invoiceId(), inv.getDocumentNo(),
                        inv.getGrandTotal().setScale(2, java.math.RoundingMode.HALF_UP), inv.getDateInvoiced().toLocalDateTime().toLocalDate(),
                        inv.getC_BPartner_ID()));
        return "EMIS";
    }

