    /**
     * Linia generatorului pentru setul {@code produs} × {@code cant} la prețul brut {@code pretBrut}: componentele listei (în tranzacția
     * procesului, X257), prețul net al setului repartizat proporțional cu prețul de listă × bucăți ({@link SetLista#explodeaza}, 2 zecimale),
     * cota setului; setul nu e stocabil (stocul se descarcă pe componente).
     */
    static GeneratorDocumente.Linie linieSet(int client, int idLinie, int produs, BigDecimal cant, BigDecimal pretBrut, int cotaLegala,
            int listaPret, String trx) {
        List<SetLista.Componenta> comp = SetLista.componente(client, produs, trx);
        Timestamp azi = Timestamp.valueOf(LocalDate.now(com.eva.ro.contab.form.OraRO.ZONA).atStartOfDay());
        Map<Integer, BigDecimal> pl = new LinkedHashMap<>();
        for (SetLista.Componenta k : comp)
            pl.put(k.produs(), dublaPret != null ? dublaPret.pret(trx, client, listaPret, k.produs(), azi)
                    : DB.getSQLValueBDEx(trx, SQL_PRET_LISTA, client, listaPret, k.produs(), azi));
        List<SetLista.LinieComponenta> lc = SetLista.explodeaza(comp, cant, GeneratorDocumente.pretNet(pretBrut, cotaLegala), pl, 2);
        return new GeneratorDocumente.Linie(idLinie, produs, cant, pretBrut, cotaLegala, false, null, List.of(), lc);
    }
