/**
 * P01.T354 (P01.C03.T0028) lotul B — garda «linie cu articol-set în afara generatorului» (D-T354-3, D-ORC-6, D-ORC-7; plan §5.2 (4),
 * anexa R17 / R26 / R28), pe documentele NATIVE ale vânzării, oricare ar fi ecranul (comenzi K12, ieșiri K13, copia și nota de credit,
 * contractele, ferestrele native):
 * <ul>
 *   <li>{@code DOC_BEFORE_PREPARE} pe {@link #TABELE} (rulat și din {@code completeIt}, care cheamă {@code prepareIt}): documentul cu o
 *   linie al cărei produs e {@code SetLista.stare(...).candidat()} (orice listă; linie nouă SAU produs schimbat pe o linie DR) se refuză
 *   cu {@link SetLista#K_MANUAL} + motivul listei; nativul întoarce {@code STATUS_Invalid}, documentul rămâne nefinalizat. Scutite:
 *   inversul ({@code Reversal_ID > 0}, setat înaintea {@code processIt} al stornării; liniile lui se copiază ÎNAINTE, de aceea nimic
 *   pe {@code PO_BEFORE_NEW} al liniei) și documentul înregistrat de generator ({@link SetLista#dinGenerator}, doar el, în tranzacția
 *   lui);</li>
 *   <li>{@code DOC_BEFORE_REACTIVATE} pe aceleași tabele: documentul finalizat cu o linie-candidat nu se devalidează
 *   ({@link SetLista#K_MANUAL} + {@link #K_DEVALIDARE}, trimiterea la stornare); evenimentul vine înaintea ștergerii notelor ({@code MInvoice} 2870 &lt; 2899,
 *   {@code MOrder} 3048 &lt; 3081), deci documentul rămâne {@code CO} cu notele. Fără scutiri: inversul nu se devalidează nativ.</li>
 * </ul>
 * Decizia e pură ({@link #decizie}); citirile trec prin {@link Surse} (producția = {@link #BAZA}), în tranzacția documentului.
 * Înregistrat programatic în {@code EvaActivator} (blocul {@code // P01.T354}).
 */
public class EvaSetLinieEvents extends AbstractEventHandler {

    /** Documentele vânzării păzite (C-23: comenzi, livrări, facturi). */
    public static final String[] TABELE = {"C_Order", "M_InOut", "C_Invoice"};
    /** Evenimentele păzite: pregătirea (R17 / R26) și devalidarea (R28). */
    public static final String[] EVENIMENTE = {IEventTopics.DOC_BEFORE_PREPARE, IEventTopics.DOC_BEFORE_REACTIVATE};
    /** Trimiterea la stornare a refuzului devalidării (R28: {@link SetLista#K_MANUAL} + această trimitere). */
    public static final String K_DEVALIDARE = "t354.refuz.devalidare";

    @Override
    protected void initialize() {
        for (String e : EVENIMENTE)
            for (String t : TABELE)
                registerTableEvent(e, t);
    }

    @Override
    protected void doHandleEvent(Event event) {
        String eroare = laEveniment(event.getTopic(), getPO(event), BAZA);
        if (eroare != null)
            addErrorMessage(event, eroare);
    }

    /** O linie a documentului: produsul, codul lui și cele trei atribute ale regulii «candidat» (R1). */
    public record Linie(int produs, String cod, boolean isBom, boolean isStocked, String tip) {
    }

    /** Citirile gărzii; producția = {@link #BAZA}. */
    public interface Surse {
        /** Documentul a fost înregistrat de generatorul seturilor în tranzacția lui ({@link SetLista#dinGenerator}). */
        boolean dinGenerator(String trx, String tabela, int id);

        /** Liniile cu produs ale documentului (doar ale lui, pe firmă), în ordinea liniilor. */
        List<Linie> linii(int client, String tabela, int id, String trx);

        /** Starea setului produsului ({@link SetLista#stare}), pe firmă, în tranzacția documentului. */
        SetLista.StareSet stare(int client, int produs, String trx);
    }

    /**
     * Emisia (statică, X184): evenimentul + PO-ul → {@link #decizie}. Firma nedeterminată ({@code AD_Client_ID ≤ 0}) ⇒ refuzul
     * {@link SetLista#K_FIRMA} (X207), fără nicio citire. Inversul se citește doar unde tabela are coloana {@code Reversal_ID}
     * ({@code C_Order} nu o are, pasul 0 S0-3). Generatorul se întreabă doar la pregătire.
     */
    public static String laEveniment(String topic, PO po, Surse s) {
        boolean areColoana = po.get_ColumnIndex("Reversal_ID") >= 0;
        boolean inversare = inversare(areColoana, areColoana ? po.get_ValueAsInt("Reversal_ID") : 0);
        return laDocument(topic, po.getAD_Client_ID(), po.get_TableName(), po.get_ID(), po.get_TrxName(), inversare, s);
    }

    /** Documentul e inversul unei stornări (R26): tabela are coloana {@code Reversal_ID} și valoarea ei e &gt; 0 (pur, testat pe capete). */
    static boolean inversare(boolean areColoana, int reversalId) {
        return areColoana && reversalId > 0;
    }

    /**
     * Lipiciul (static, fără PO, executat de test pe valoare — X216): firma ≤ 0 ⇒ {@link SetLista#K_FIRMA} fără nicio citire; altfel
     * semnalul generatorului (doar la pregătire, doar pe documentul ne-invers), liniile ACESTUI document și starea fiecărui produs, toate
     * pe firma și în tranzacția documentului, apoi {@link #decizie}.
     */
    static String laDocument(String topic, int client, String tabela, int id, String trx, boolean inversare, Surse s) {
        if (client <= 0)
            return Etichete.t(SetLista.K_FIRMA);
        boolean devalidare = IEventTopics.DOC_BEFORE_REACTIVATE.equals(topic);
        boolean generator = !devalidare && !inversare && s.dinGenerator(trx, tabela, id);
        return decizie(devalidare, inversare, generator, s.linii(client, tabela, id, trx), p -> s.stare(client, p, trx));
    }

    /**
     * Decizia (pură, C-23 / C-24): la pregătire inversul și documentul generatorului sunt scutite; altfel prima linie al cărei produs
     * trece de {@link SetLista#candidat} și pe care {@code stare} o confirmă candidat ⇒ refuzul (pregătire: {@link SetLista#K_MANUAL}
     * cu codul și motivul listei; devalidare: același {@link SetLista#K_MANUAL} urmat de trimiterea la stornare {@link #K_DEVALIDARE},
     * R28); altfel {@code null}.
     */
    public static String decizie(boolean devalidare, boolean inversare, boolean dinGenerator, List<Linie> linii,
            java.util.function.IntFunction<SetLista.StareSet> stare) {
        if (!devalidare && (inversare || dinGenerator))
            return null;
        for (Linie l : linii) {
            if (!SetLista.candidat(l.isBom(), l.isStocked(), l.tip()))
                continue;
            SetLista.StareSet st = stare.apply(l.produs());
            if (st == null || !st.candidat())
                continue;
            String manual = Etichete.t(SetLista.K_MANUAL, l.cod(), motivLista(st.refuz()));
            return devalidare ? manual + " " + Etichete.t(K_DEVALIDARE, l.cod()) : manual;
        }
        return null;
    }

    /** Motivul listei din {@code StareSet.refuz()}: cheia tradusă dacă e cheie, textul ca atare altfel; {@code null} = lista validă. */
    public static String motivLista(String refuz) {
        if (refuz == null)
            return Etichete.t("t354.b.lista_valida");
        return Etichete.exista(refuz) ? Etichete.t(refuz) : refuz;
    }

    /**
     * SELECT-ul (pur) al liniilor cu produs ale documentului, cu atributele regulii «candidat»; parametrii: firma, id-ul documentului.
     * Tabela din lista închisă {@link #TABELE}, altfel excepție (X137).
     */
    public static String sqlLinii(String tabela) {
        String linie, doc;
        if ("C_Order".equalsIgnoreCase(tabela)) {
            linie = "c_orderline"; doc = "c_order_id";
        } else if ("M_InOut".equalsIgnoreCase(tabela)) {
            linie = "m_inoutline"; doc = "m_inout_id";
        } else if ("C_Invoice".equalsIgnoreCase(tabela)) {
            linie = "c_invoiceline"; doc = "c_invoice_id";
        } else
            throw new IllegalArgumentException(String.valueOf(tabela));
        return "SELECT l.m_product_id, p.value, p.isbom, p.isstocked, p.producttype FROM " + linie + " l"
                + " JOIN m_product p ON p.m_product_id=l.m_product_id AND p.ad_client_id=l.ad_client_id"
                + " WHERE l.ad_client_id=? AND l." + doc + "=? AND l.m_product_id>0 ORDER BY l.line, l." + linie + "_id";
    }

    /** Liniile din rândurile citite (pur față de bază, X213: {@code ResultSet} dat). */
    public static List<Linie> linii(java.sql.ResultSet rs) throws java.sql.SQLException {
        List<Linie> l = new ArrayList<>();
        while (rs.next())
            l.add(new Linie(rs.getInt(1), rs.getString(2), "Y".equals(rs.getString(3)), "Y".equals(rs.getString(4)), rs.getString(5)));
        return l;
    }

    /** Sursele de producție: semnalul generatorului, liniile documentului pe firmă, starea setului — toate în tranzacția dată. */
    public static final Surse BAZA = new Surse() {
        @Override
        public boolean dinGenerator(String trx, String tabela, int id) {
            return SetLista.dinGenerator(trx, tabela, id);
        }

        @Override
        public List<Linie> linii(int client, String tabela, int id, String trx) {
            String sql = sqlLinii(tabela);
            try (java.sql.PreparedStatement ps = org.compiere.util.DB.prepareStatement(sql, trx)) {
                ps.setInt(1, client);
                ps.setInt(2, id);
                try (java.sql.ResultSet rs = ps.executeQuery()) {
                    return EvaSetLinieEvents.linii(rs);
                }
            } catch (java.sql.SQLException e) {
                throw new org.adempiere.exceptions.DBException(e, sql);
            }
        }

        @Override
        public SetLista.StareSet stare(int client, int produs, String trx) {
            return SetLista.stare(client, produs, trx);
        }
    };
}
