/**
 * P01.T331 (P01.C03.T0017; contractul {@code 04_} F-8 (a)–(i) + F-2, spec {@code 05_} A-7) — gărzile de izolare ale gestiunii
 * WMS pereche W, pe orice cale care salvează sau procesează (ecranele EvA, ferestrele native, REST, procese):
 * <ul>
 * <li>(a) {@code DOC_BEFORE_PREPARE} / {@code DOC_BEFORE_COMPLETE} pe {@code M_Inventory}, {@code M_Movement}, {@code M_InOut},
 * {@code M_Production}: oricare din cele 11 coloane de gestiune / locator ({@link #COLOANE_DOCUMENT}) pe W ⇒ refuz (registrul WMS
 * rămâne {@code DR});</li>
 * <li>(a′) {@code PO_BEFORE_CHANGE} pe {@code M_Inventory} pe W: {@code DocStatus} {@code DR} → altă stare ⇒ refuz (fereastra
 * nativă refuzată la pregătire ar salva {@code IN}; {@code 20_} C-9);</li>
 * <li>(b) {@code C_Order} / {@code C_OrderLine} cu gestiunea W la salvare și {@code C_Order} la pregătire;</li>
 * <li>(c) {@code EVA_SursaSite}: gestiunea sursei sau gestiunile canalului pe W;</li>
 * <li>(d) {@code M_Warehouse} legată (G sau W): demarcarea W, G → GV_*, inactivarea / ștergerea; (e) gestiune NOUĂ cu NC fără
 * jetonul activării;</li>
 * <li>(f) / (g) / (g′) registrul WMS: anularea, ștergerea, ștergerea liniei validate;</li>
 * <li>(h) zonele perechii și pozițiile lui W cu stoc validat;</li>
 * <li>(i) corectarea locatorului liniei de producție pe G ({@code M_ProductionLine}, doar; mișcările rămân sub (a));</li>
 * <li>F-2: rândul {@code EVA_PerecheWms} nu se modifică / șterge în afara activării.</li>
 * </ul>
 * Decizia stă în {@link #decide} (fără bază: obiectul și sursele sunt interfețe), regulile în {@link GardaWms} (pure). Firmele
 * fără gestiune NC ies imediat, fără nicio altă citire (garda de disponibilitate, X108; C-331.8). Refuzurile devin erori ale
 * evenimentului, traduse; excepțiile de bază se propagă (nimic nu se înghite). Înregistrat în {@code EvaActivator} (lotul A).
 */
public class EvaWmsGardaEvents extends AbstractEventHandler {

    /** (a) documentele de stoc. */
    public static final String[] TABELE_DOCUMENT = {"M_Inventory", "M_Movement", "M_InOut", "M_Production"};
    /** (a) cele 11 coloane de gestiune / locator (06d §D.3 a): {antet, tabela coloanei, coloana, «W» = gestiune / «L» = locator}. */
    public static final String[][] COLOANE_DOCUMENT = {
        {"M_Inventory", "M_Inventory", "M_Warehouse_ID", "W"},
        {"M_Inventory", "M_InventoryLine", "M_Locator_ID", "L"},
        {"M_Movement", "M_Movement", "M_Warehouse_ID", "W"},
        {"M_Movement", "M_Movement", "M_WarehouseTo_ID", "W"},
        {"M_Movement", "M_MovementLine", "M_Locator_ID", "L"},
        {"M_Movement", "M_MovementLine", "M_LocatorTo_ID", "L"},
        {"M_InOut", "M_InOut", "M_Warehouse_ID", "W"},
        {"M_InOut", "M_InOutLine", "M_Locator_ID", "L"},
        {"M_Production", "M_Production", "M_Locator_ID", "L"},
        {"M_Production", "M_ProductionLine", "M_Locator_ID", "L"},
        {"M_Production", "M_ProductionPlan", "M_Locator_ID", "L"},
    };
    public static final String COMANDA = "C_Order", LINIE_COMANDA = "C_OrderLine", SURSA = "EVA_SursaSite",
            GESTIUNE = "M_Warehouse", INVENTAR = "M_Inventory", LINIE_INVENTAR = "M_InventoryLine", LOCATOR = "M_Locator",
            LINIE_PRODUCTIE = "M_ProductionLine", PERECHE = "EVA_PerecheWms";
    public static final String COL_WH = "M_Warehouse_ID", COL_LOC = "M_Locator_ID", COL_ACTIV = "IsActive", COL_VALOARE = "Value",
            COL_GESTIUNI_STOC = "EVA_GestiuniStoc", COL_QTY_COUNT = "QtyCount", COL_STARE = "DocStatus";

    /** Evenimentele înregistrate: subiect → tabele (testat în TestGestiuneNecontabila: (i) DOAR pe M_ProductionLine). */
    public static final Map<String, List<String>> EVENIMENTE = Map.of(
            IEventTopics.DOC_BEFORE_PREPARE, List.of("M_Inventory", "M_Movement", "M_InOut", "M_Production", COMANDA),
            IEventTopics.DOC_BEFORE_COMPLETE, List.of(TABELE_DOCUMENT),
            IEventTopics.DOC_BEFORE_VOID, List.of(INVENTAR),
            IEventTopics.PO_BEFORE_NEW, List.of(COMANDA, LINIE_COMANDA, SURSA, GESTIUNE, LINIE_PRODUCTIE),
            IEventTopics.PO_BEFORE_CHANGE, List.of(COMANDA, LINIE_COMANDA, SURSA, GESTIUNE, LOCATOR, LINIE_PRODUCTIE, PERECHE, INVENTAR),
            IEventTopics.PO_BEFORE_DELETE, List.of(GESTIUNE, INVENTAR, LINIE_INVENTAR, LOCATOR, PERECHE));

    @Override
    protected void initialize() {
        for (Map.Entry<String, List<String>> e : EVENIMENTE.entrySet())
            for (String t : e.getValue())
                registerTableEvent(e.getKey(), t);
    }

    @Override
    protected void doHandleEvent(Event event) {
        PO po = getPO(event);
        String cheie = decide(new ObiectPo(po), event.getTopic(), BAZA);
        if (cheie != null)
            addErrorMessage(event, Etichete.t(cheie));
    }

    // ───────────────────────────────────────────── vederea obiectului și sursele (fără bază în test)

    /** Ce citește garda din obiectul evenimentului. */
    public interface Obiect {
        String tabela();

        int id();

        int client();

        String trx();

        Object valoare(String coloana);

        Object vechi(String coloana);

        boolean schimbat(String coloana);

        void seteaza(String coloana, Object valoare);
    }

    /** Ce citește garda din bază (implementarea reală: {@link #BAZA}; în test: dublă). */
    public interface Surse {
        Set<Integer> necontabile(int client, String trx);

        List<Integer> gestiuniDocument(String tabela, int client, int id, String trx);

        List<Integer> gestiuniComanda(int client, int comanda, String trx);

        PerecheWms dupaContabila(int client, int wh, String trx);

        PerecheWms dupaWms(int client, int wh, String trx);

        int gestiuneLocator(int client, int locator, String trx);

        int locatorProductie(int client, int productie, String trx);

        int locatorImplicit(int client, int wh, String trx);

        int gestiuneInventar(int client, int inventar, String trx);

        boolean areValidareActiva(int client, int linieInventar, String trx);

        BigDecimal cantitateLocator(int client, int locator, String trx);

        boolean jeton();
    }

    private static int intreg(Object o) {
        return o instanceof Number n ? n.intValue() : 0;
    }

    /** Steag Yes-No citit cu get_Value (Boolean) sau ca text «Y» — nu cu get_ValueAsString (X125). */
    static boolean da(Object o) {
        return Boolean.TRUE.equals(o) || "Y".equals(o);
    }

    /**
     * Decizia gărzii pe obiectul și subiectul evenimentului: cheia refuzului sau null. Pe (i) corectează locatorul liniei prin
     * {@link Obiect#seteaza} și întoarce null. Firma fără gestiuni NC ⇒ null fără altă citire (în afară de (e), care nu citește
     * baza).
     */
    public static String decide(Obiect o, String topic, Surse s) {
        String tab = o.tabela();
        boolean nou = IEventTopics.PO_BEFORE_NEW.equals(topic), schimbare = IEventTopics.PO_BEFORE_CHANGE.equals(topic),
                stergere = IEventTopics.PO_BEFORE_DELETE.equals(topic);
        if (GESTIUNE.equals(tab) && nou)
            return GardaWms.refuzGestiuneNoua((String) o.valoare(TipGestiune.COL_TIP), s.jeton());           // (e)
        if (PERECHE.equals(tab) && (schimbare || stergere))
            return GardaWms.refuzModificarePereche(s.jeton());                                              // F-2
        int client = o.client();
        if (client <= 0)
            return null;   // System: nicio gestiune NC (activarea cere firma > 0)
        Set<Integer> nc = s.necontabile(client, o.trx());
        if (nc == null || nc.isEmpty())
            return null;   // X108 / C-331.8: firma fără pereche — nimic de păzit
        String trx = o.trx();
        if (List.of(TABELE_DOCUMENT).contains(tab) && (IEventTopics.DOC_BEFORE_PREPARE.equals(topic)
                || IEventTopics.DOC_BEFORE_COMPLETE.equals(topic)))
            return GardaWms.refuzDocument(s.gestiuniDocument(tab, client, o.id(), trx), nc);              // (a)
        if (INVENTAR.equals(tab) && IEventTopics.DOC_BEFORE_VOID.equals(topic))
            return GardaWms.refuzAnulareRegistru(nc.contains(intreg(o.valoare(COL_WH))));                  // (f)
        if (INVENTAR.equals(tab) && schimbare && o.schimbat(COL_STARE)) {                                   // (a′) 20_ C-9
            boolean peW = nc.contains(intreg(o.valoare(COL_WH))) || (o.schimbat(COL_WH) && nc.contains(intreg(o.vechi(COL_WH))));
            return GardaWms.refuzStareRegistru(peW, (String) o.vechi(COL_STARE), (String) o.valoare(COL_STARE), s.jeton());
        }
        if (INVENTAR.equals(tab) && stergere)
            return GardaWms.refuzStergereRegistru(nc.contains(intreg(o.valoare(COL_WH))));                 // (g)
        if (LINIE_INVENTAR.equals(tab) && stergere) {                                                      // (g′)
            boolean peW = nc.contains(s.gestiuneInventar(client, intreg(o.valoare("M_Inventory_ID")), trx));
            if (!peW)
                return null;
            BigDecimal qty = o.valoare(COL_QTY_COUNT) instanceof BigDecimal b ? b : null;
            return GardaWms.refuzStergereLinie(true, RegistruWms.nevalidat(qty, s.areValidareActiva(client, o.id(), trx)));
        }
        if ((COMANDA.equals(tab) || LINIE_COMANDA.equals(tab)) && (nou || schimbare))
            return GardaWms.refuzComanda(List.of(intreg(o.valoare(COL_WH))), nc);                          // (b)
        if (COMANDA.equals(tab) && IEventTopics.DOC_BEFORE_PREPARE.equals(topic))
            return GardaWms.refuzComanda(s.gestiuniComanda(client, o.id(), trx), nc);                       // (b)
        if (SURSA.equals(tab) && (nou || schimbare))
            return GardaWms.refuzSursa(intreg(o.valoare(COL_WH)), (String) o.valoare(COL_GESTIUNI_STOC), nc); // (c)
        if (GESTIUNE.equals(tab) && (schimbare || stergere)) {                                              // (d)
            int wh = o.id();
            boolean eW = nc.contains(wh) && s.dupaWms(client, wh, trx) != null;
            boolean eG = !eW && s.dupaContabila(client, wh, trx) != null;
            boolean activVechi = stergere || !o.schimbat(COL_ACTIV) ? da(o.valoare(COL_ACTIV)) : da(o.vechi(COL_ACTIV));
            return GardaWms.refuzGestiune(eG, eW, (String) o.valoare(TipGestiune.COL_TIP), activVechi,
                    stergere ? false : da(o.valoare(COL_ACTIV)), stergere);
        }
        if (LOCATOR.equals(tab) && (schimbare || stergere)) {                                               // (h)
            int whVechi = schimbare && o.schimbat(COL_WH) ? intreg(o.vechi(COL_WH)) : intreg(o.valoare(COL_WH));
            if (!nc.contains(whVechi))
                return null;
            PerecheWms p = s.dupaWms(client, whVechi, trx);
            int loc = o.id();
            boolean eZona = p != null && (loc == p.locatorReceptie() || loc == p.locatorExpediere() || loc == p.locatorNeamplasat());
            boolean inactivat = schimbare && o.schimbat(COL_ACTIV) && !da(o.valoare(COL_ACTIV));
            boolean mutat = schimbare && o.schimbat(COL_WH), recodificat = schimbare && o.schimbat(COL_VALOARE);
            BigDecimal qty = eZona || !(stergere || inactivat) ? null : s.cantitateLocator(client, loc, trx);
            return GardaWms.refuzLocator(true, eZona, qty, stergere, inactivat, mutat, recodificat);
        }
        if (LINIE_PRODUCTIE.equals(tab) && (nou || schimbare)) {                                            // (i)
            int locLinie = intreg(o.valoare(COL_LOC));
            int locAntet = s.locatorProductie(client, intreg(o.valoare("M_Production_ID")), trx);
            int whAntet = locAntet > 0 ? s.gestiuneLocator(client, locAntet, trx) : 0;
            int corectat = GardaWms.locatorCorectat(locLinie, whAntet, l -> s.gestiuneLocator(client, l, trx), g -> {
                PerecheWms p = s.dupaContabila(client, g, trx);
                return p == null ? 0 : p.gestiuneWms();
            }, g -> s.locatorImplicit(client, g, trx));
            if (corectat != locLinie)
                o.seteaza(COL_LOC, corectat);
            return null;
        }
        return null;
    }

    // ───────────────────────────────────────────── SQL (parametrizat; fiecare cu AD_Client_ID=?)

    /** PUR: SQL-ul gestiunilor unui document de stoc pe cele 11 coloane; parametrii: (firma, id) × numărul ramurilor. */
    public static String sqlGestiuniDocument(String antet) {
        StringBuilder sb = new StringBuilder();
        for (String[] c : COLOANE_DOCUMENT) {
            if (!c[0].equals(antet))
                continue;
            if (sb.length() > 0)
                sb.append(" UNION ");
            if ("W".equals(c[3]))
                sb.append("SELECT x.").append(c[2]).append(" FROM ").append(c[1]).append(" x");
            else
                sb.append("SELECT l.M_Warehouse_ID FROM ").append(c[1]).append(" x JOIN M_Locator l ON l.M_Locator_ID=x.").append(c[2])
                        .append(" AND l.AD_Client_ID=x.AD_Client_ID");
            sb.append(" WHERE x.AD_Client_ID=? AND x.").append(c[0]).append("_ID=?");
        }
        return sb.toString();
    }

    /** Numărul ramurilor {@code UNION} ale lui {@link #sqlGestiuniDocument} (fiecare cere firma și id-ul). */
    public static int ramuriDocument(String antet) {
        int n = 0;
        for (String[] c : COLOANE_DOCUMENT)
            if (c[0].equals(antet))
                n++;
        return n;
    }

    public static final String SQL_GESTIUNI_COMANDA = "SELECT M_Warehouse_ID FROM C_Order WHERE AD_Client_ID=? AND C_Order_ID=?"
            + " UNION SELECT M_Warehouse_ID FROM C_OrderLine WHERE AD_Client_ID=? AND C_Order_ID=?";
    public static final String SQL_GESTIUNE_LOCATOR = "SELECT M_Warehouse_ID FROM M_Locator WHERE AD_Client_ID=? AND M_Locator_ID=?";
    public static final String SQL_LOCATOR_PRODUCTIE = "SELECT M_Locator_ID FROM M_Production WHERE AD_Client_ID=? AND M_Production_ID=?";
    /** Locatorul implicit al gestiunii: întâi IsDefault, apoi prioritatea și id-ul (ca {@code MWarehouse.getDefaultLocator}). */
    public static final String SQL_LOCATOR_IMPLICIT = "SELECT M_Locator_ID FROM M_Locator WHERE AD_Client_ID=? AND M_Warehouse_ID=?"
            + " AND IsActive=? ORDER BY CASE WHEN IsDefault=? THEN 0 ELSE 1 END, PriorityNo, M_Locator_ID FETCH FIRST 1 ROWS ONLY";
    public static final String SQL_GESTIUNE_INVENTAR = "SELECT M_Warehouse_ID FROM M_Inventory WHERE AD_Client_ID=? AND M_Inventory_ID=?";
    /**
     * Condiția unică «mișcarea {@code m} e o VALIDARE activă, neinversată, a unei linii de registru» (parametrii
     * {@link #parametriValidare()}); folosită de garda (g′) și de grila «Gestiunea WMS» (o singură regulă, X111).
     */
    public static final String CONDITIE_VALIDARE = " m.AD_Table_ID=? AND m.EVA_TipMiscareWms=? AND m.IsActive=?"
            + " AND NOT EXISTS (SELECT 1 FROM EVA_MiscareWms s WHERE s.AD_Client_ID=m.AD_Client_ID"
            + " AND s.EVA_MiscareWmsInversa_ID=m.EVA_MiscareWms_ID AND s.IsActive=?)";
    /** Linia registrului are o mișcare VALIDARE activă, neinversată (parametrii: firma, linia, apoi {@link #parametriValidare()}). */
    public static final String SQL_VALIDARE_ACTIVA = "SELECT COUNT(*) FROM EVA_MiscareWms m WHERE m.AD_Client_ID=?"
            + " AND m.EVA_LinieSursa_ID=? AND" + CONDITIE_VALIDARE;

    /** Parametrii lui {@link #CONDITIE_VALIDARE}, în ordine: tabela liniei registrului, tipul VALIDARE, Y, Y. */
    public static Object[] parametriValidare() {
        return new Object[] {org.compiere.model.MInventoryLine.Table_ID, TipMiscareWms.VALIDARE.name(), "Y", "Y"};
    }
    public static final String SQL_CANTITATE_LOCATOR = "SELECT COALESCE(SUM(Qty),0) FROM EVA_StocWms WHERE AD_Client_ID=? AND M_Locator_ID=?";

    private static void firma(int client) {
        if (client <= 0)
            throw new IllegalArgumentException("AD_Client_ID " + client);
    }

    private static List<Integer> ids(String sql, String trx, Object... p) {
        List<Integer> out = new ArrayList<>();
        try (PreparedStatement ps = DB.prepareStatement(sql, trx)) {
            DB.setParameters(ps, p);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next())
                    out.add(rs.getInt(1));
            }
        } catch (SQLException e) {
            throw new DBException(e, sql);
        }
        return out;
    }

    /** Parametrii lui {@link #sqlGestiuniDocument}: (firma, id) repetat pe fiecare ramură. */
    public static Object[] parametriDocument(String antet, int client, int id) {
        int n = ramuriDocument(antet);
        Object[] p = new Object[2 * n];
        for (int i = 0; i < n; i++) {
            p[2 * i] = client;
            p[2 * i + 1] = id;
        }
        return p;
    }

    /** Sursele reale (baza iDempiere); fiecare metodă refuză firma nedeterminată (X18 / X207). */
    public static final Surse BAZA = new Surse() {
