    private static Rezultat emiteFaraSavepoint(Properties ctx, ComandaDeEmis c, Setari s, String trx) throws Exception {
        int client = c.client();
        // 1. garda stocului negativ, sub blocare, pe SUMA liniilor valului pe cheie (75m D-2)
        // 74p F-5: blocările în ordine FIXĂ (articolele crescător; în interiorul articolului locație, ASI — RezervareStoc)
        Map<String, BigDecimal> fizic = RezervareStoc.blocheaza(client, produseStocabile(c.linii()), s.gestiune(), trx);
        List<RezervareStoc.LinieCerere> cereri = cereriVal(c.linii(), s.gestiune());   // P01.T354 A: setul pe componente
        Set<Integer> peste = RezervareStoc.liniiPesteStoc(cereri, fizic);   // P01.T354 A (R7): setul decis atomic (grupat pe linie)
        // 95a B-2 / Q-95a-1: la EVA_T22_LIVRARE_PARTIALA = N orice linie peste stoc refuză TOT valul (rollback, 0 documente);
        // la Y liniile peste stoc devin ROȘII și restul valului se emite
        if (decizieGarda(peste, c.livrarePartiala()) == DecizieGarda.REFUZ_VAL)
            throw new Refuz(Etichete.t("vanzari.stoc.negativ_interzis", peste), liniiRefuzate(peste));
        Map<Integer, String> rosii = new LinkedHashMap<>();
        List<Linie> val = new ArrayList<>();
        for (Linie l : c.linii())
            if (peste.contains(l.idLinie()))
                rosii.put(l.idLinie(), "V18:" + ValidareComanda.STOC_INSUFICIENT);
            else
                val.add(l);
        if (val.isEmpty())
            return new Rezultat(0, 0, 0, rosii, null);
        Timestamp dataCmd = Timestamp.valueOf(c.data().atStartOfDay());
        Timestamp dataFact = Timestamp.valueOf(c.dataFactura().atStartOfDay());
        // P01.T203 A-6: seriile fiecărei linii (a doua barieră după SERII / V17): forma pe cantitate, unicitatea tipului 2, stocul ≥ 1 al
        // instanței tipului 3 în gestiunea comenzii, sub lacăt (X130)
        Map<Integer, List<Bucata>> bucatiLinie = new LinkedHashMap<>();
        for (Linie l : val) {
            List<Bucata> b = l.stocabil() ? bucati(l.tipSerie(), l.serii(), l.cantitate()) : List.of(new Bucata(0, null, l.cantitate()));
            if (b == null)
                throw new Refuz(Etichete.t("vanzari.validare.serii_invalide"), liniiProdus(val, l.produs()));
            String[] rs = l.stocabil() && l.tipSerie() != null
                    ? SeriiArticole.refuzSeriiVanzare(client, l.produs(), l.tipSerie(), l.serii(), s.gestiune(), trx) : null;
            if (rs != null)
                throw new Refuz(Etichete.t(rs[0], rs[1], org.compiere.model.MProduct.get(ctx, l.produs()).getValue()), liniiProdus(val, l.produs()));
            bucatiLinie.put(l.idLinie(), b);
        }
        // 2. partenerul
        int[] bp = partener(ctx, c, s, trx);
        // 3. comanda
        MOrder o = new MOrder(ctx, 0, trx);
        o.setAD_Org_ID(s.org());
        o.setIsSOTrx(true);
        o.setC_DocTypeTarget_ID(s.docComanda());
        o.setC_DocType_ID(s.docComanda());
        o.setBPartner(new MBPartner(ctx, bp[0], trx)); // P01.T203 D-39: partenerul PF abia creat în trx (MBPartner.get fără trx nu-l vedea)
        o.setC_BPartner_Location_ID(bp[1]);
        o.setBill_BPartner_ID(bp[0]);
        o.setBill_Location_ID(bp[1]);
        o.setM_Warehouse_ID(s.gestiune());
        o.setM_PriceList_ID(s.listaPret());
        o.setC_PaymentTerm_ID(s.termenPlata());
        o.setDateOrdered(dataCmd);
        o.setDatePromised(dataCmd);
        o.setDateAcct(dataFact);
        o.setPOReference(c.nrComanda());
        o.setDescription(Etichete.t("vanzari.doc.descriere_comanda", c.nrComanda(), c.sursa()));
        o.saveEx();
        Map<Integer, MOrderLine> peLinie = new LinkedHashMap<>();
        Map<Integer, List<MOrderLine>> liniiComanda = new LinkedHashMap<>();   // P01.T203 D-33: tipul 3 = o linie pe serie
        Map<Integer, MOrderLine> peIdComanda = new LinkedHashMap<>();
        Map<Integer, BigDecimal> bazaPeCota = new LinkedHashMap<>();
        int nr = 0;
        for (Linie l : val) {
            if (l.esteSet()) {   // P01.T354 A (D-ORC-1 V2): descrierea setului fără produs + componentele la prețul repartizat, cota setului
                String numeSet = org.compiere.model.MProduct.get(ctx, l.produs()).getName();
                int taxa = com.eva.ro.contab.form.ContabUtil.taxaPentruCota(BigDecimal.valueOf(l.cotaLegala()), client, true, dataFact);
                MOrderLine d = new MOrderLine(o);
                d.setLine(nr += 10);
                d.setDescription(numeSet);
                d.setQty(l.cantitate());
                d.setPriceList(BigDecimal.ZERO);
                d.setPrice(BigDecimal.ZERO);
                d.setC_Tax_ID(taxa);
                d.saveEx();
                peLinie.put(l.idLinie(), d);
                liniiComanda.computeIfAbsent(l.idLinie(), x -> new ArrayList<>()).add(d);
                peIdComanda.put(d.getC_OrderLine_ID(), d);
                for (SetLista.LinieComponenta x : l.componente()) {
                    MOrderLine ol = new MOrderLine(o);
                    ol.setLine(nr += 10);
                    ol.setM_Product_ID(x.produs(), true);
                    ol.setQty(x.cantitate());
                    ol.setPriceList(x.pretNetUnitar());
                    ol.setPrice(x.pretNetUnitar());
                    ol.setC_Tax_ID(taxa);
                    ol.setDescription(numeSet);   // copiată nativ pe livrare și factură (MInOutLine.setOrderLine, MInvoiceLine.setShipLine)
                    ol.saveEx();
                    liniiComanda.get(l.idLinie()).add(ol);
                    peIdComanda.put(ol.getC_OrderLine_ID(), ol);
                    bazaPeCota.merge(l.cotaLegala(), x.pretNetUnitar().multiply(x.cantitate()), BigDecimal::add);
                }
                continue;
            }
            BigDecimal net = pretNet(l.pretBrutLei(), l.cotaLegala());
            List<Bucata> pe = l.stocabil() && liniePeSerie(l.tipSerie()) ? bucatiLinie.get(l.idLinie()) : List.of(new Bucata(0, null, l.cantitate()));
            for (Bucata b : pe) {
                MOrderLine ol = new MOrderLine(o);
                ol.setLine(nr += 10);
                ol.setM_Product_ID(l.produs(), true);
                ol.setQty(b.cantitate());
                if (b.instanta() > 0)
                    ol.setM_AttributeSetInstance_ID(b.instanta());
                ol.setPriceList(net);
                ol.setPrice(net);
                ol.setC_Tax_ID(com.eva.ro.contab.form.ContabUtil.taxaPentruCota(BigDecimal.valueOf(l.cotaLegala()), client, true, dataFact));
                ol.saveEx();
                peLinie.putIfAbsent(l.idLinie(), ol);
                liniiComanda.computeIfAbsent(l.idLinie(), x -> new ArrayList<>()).add(ol);
                peIdComanda.put(ol.getC_OrderLine_ID(), ol);
                bazaPeCota.merge(l.cotaLegala(), net.multiply(b.cantitate()), BigDecimal::add);
            }
        }
        List<MOrderLine> servicii = new ArrayList<>();
        if (c.primulVal()) {
            int cotaServ = bazaPeCota.isEmpty() ? 0 : bazaPeCota.keySet().iterator().next();
            // 74o D-B2: c.transport() = transportul FACTURAT (TarifTransport.calculeaza; null / 0 = «apare pe factură» Nu ⇒ 0 linii);
            // net = brut / (1 + cota articolului «Transport»)
            if (c.transport() != null && c.transport().signum() != 0)
                servicii.add(linieServiciu(o, nr += 10, s.articolTransport(), BigDecimal.ONE, c.transport(),
                        cotaArticol(s.articolTransport(), cotaServ, dataFact, trx), client, dataFact));
            if (c.discount() != null && c.discount().signum() != 0) {
                Map<Integer, BigDecimal> brutPeCota = new LinkedHashMap<>();
                for (Linie l : val)
                    brutPeCota.merge(l.cotaLegala(), l.pretBrutLei().multiply(l.cantitate()), BigDecimal::add);
                for (Map.Entry<Integer, BigDecimal> e : repartizeazaDiscount(brutPeCota, c.discount()).entrySet())
                    servicii.add(linieServiciu(o, nr += 10, s.articolDiscount(), BigDecimal.ONE, e.getValue().negate(), e.getKey(), client, dataFact));
            }
        }
        try (AutoCloseable gen = SetLista.emitere(trx, MOrder.Table_Name, o.getC_Order_ID())) {   // P01.T354 (D-ORC-6): documentul generatorului
            if (!o.processIt(DocAction.ACTION_Complete))
                throw new IllegalStateException(Etichete.t("vanzari.doc.refuz_nativ", "C_Order", o.getProcessMsg()));
        }
        o.saveEx();
