    /** Stocul pe locațiile gestiunii (cel mai mult întâi), citit în tranzacția procesului (rândurile sunt deja blocate). */
    static Map<Integer, BigDecimal> stocPeLocatii(int client, int produs, int gestiune, String trx) {
        Map<Integer, BigDecimal> m = new LinkedHashMap<>();
        try (PreparedStatement ps = DB.prepareStatement("SELECT s.m_locator_id, sum(s.qtyonhand) FROM m_storageonhand s"
                + " JOIN m_locator l ON l.m_locator_id=s.m_locator_id WHERE s.ad_client_id=? AND s.m_product_id=? AND l.m_warehouse_id=?"
                + " AND l.isactive='Y' GROUP BY s.m_locator_id HAVING sum(s.qtyonhand) > 0 ORDER BY 2 DESC, 1", trx)) {
            ps.setInt(1, client);
            ps.setInt(2, produs);
            ps.setInt(3, gestiune);
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next())
                    m.put(rs.getInt(1), rs.getBigDecimal(2));
            }
        } catch (SQLException e) {
            throw new IllegalStateException(e.getMessage(), e);
        }
        return m;
    }

