    /**
     * Stornoul NATIV al unei facturi a comenzii (74 §7.3.5 (8), 74r U7–U8; B-BE-4): {@code processIt(ACTION_Reverse_Correct)}
     * pe {@code C_Invoice}, apoi Reverse-Correct pe livrările liniilor ei ({@code M_InOut}, în ordinea id-ului; precedentul
     * {@code WSagaBonConsumForm}), în tranzacția procesului, fără savepoint: un refuz nativ ⇒ {@link IllegalStateException}
     * ({@code vanzari.doc.refuz_nativ}) ⇒ rollback complet al procesului. Factura trebuie să fie a firmei. Întoarce id-ul
     * facturii de stornare (bază).
     */
    public static int storneaza(Properties ctx, int client, int invoiceId, String trx) {
        MInvoice inv = new MInvoice(ctx, invoiceId, trx);
        if (inv.getC_Invoice_ID() != invoiceId || inv.getAD_Client_ID() != client)
            throw new IllegalStateException(Etichete.t("vanzari.doc.refuz_nativ", "C_Invoice", invoiceId));
        if (!inv.processIt(DocAction.ACTION_Reverse_Correct))
            throw new IllegalStateException(Etichete.t("vanzari.doc.refuz_nativ", "C_Invoice", inv.getProcessMsg()));
        inv.saveEx();
        for (int io : DB.getIDsEx(trx, "SELECT DISTINCT m_inout_id FROM eva_comandasitelinie WHERE ad_client_id=? AND c_invoice_id=?"
                + " AND m_inout_id > 0 ORDER BY m_inout_id", client, invoiceId)) {
            MInOut s = new MInOut(ctx, io, trx);
            if (!s.processIt(DocAction.ACTION_Reverse_Correct))
                throw new IllegalStateException(Etichete.t("vanzari.doc.refuz_nativ", "M_InOut", s.getProcessMsg()));
            s.saveEx();
        }
        return inv.getReversal_ID();
    }

