package com.eva.ro.contab.component;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Properties;
import java.util.Set;

import org.adempiere.base.event.AbstractEventHandler;
import org.adempiere.base.event.IEventTopics;
import org.compiere.model.PO;
import org.compiere.util.Env;
import org.osgi.service.event.Event;

import com.eva.ro.contab.audit.JurnalAudit;
import com.eva.ro.contab.documente.Etichete;
import com.eva.ro.contab.documente.Instantaneu;

/**
 * T42 L2 r1.2 (01b_decizii_dupa_aud2_L2_r1 B-2 / B-AUD1-1, varianta (a)) — garda de platformă: rolurile dosarului de audit
 * («Audit — …», {@link com.eva.ro.contab.audit.AuditRoluri#acces()}) NU postează și NU repostează documente ERP, pe nicio cale (butonul «Posted» al
 * ferestrei native, «Re-Post» din vizualizatorul contării, postarea imediată). {@code DOC_BEFORE_POST} pe ORICE document:
 * rolul sesiunii ∈ rolurile de audit ⇒ eroarea {@code t42.refuz.postare} + un rând {@code REFUZ} în jurnalul dosarului
 * (tranzacție proprie). Dovada la sursă (bytecode iDempiere 13, {@code L2/dovezi-be/r12/}): {@code Doc.post} șterge
 * {@code Fact_Acct} la repostare ÎNAINTEA evenimentului, dar în tranzacția {@code DocManager.postDocument}, care face rollback
 * (la savepoint) când {@code Doc.post} întoarce eroarea ⇒ notele contabile rămân neschimbate. Înregistrat în {@code EvaActivator}.
 *
 * <p>T42 L6 r1.2 (D-T6, 01b_decizii_dupa_tester_L6_r1_1 D-L6r11-1 principiul (a)): același handler ascunde textele libere ale
 * proceselor {@code EVA_Audit*} în {@code AD_PInstance_Para} LA SALVAREA rândului ({@code PO_BEFORE_NEW} / {@code PO_BEFORE_CHANGE}),
 * pe orice cale — REST {@code runProcess} și {@code runJob} (inclusiv instanța refuzată cu 409 înaintea procesului), dialogul nativ —
 * cu valoarea reală reținută doar în memorie pentru {@code prepare()} ({@code TabeleExtractie.ascundeLaSalvare} / {@code restaureaza}).
 *
 * <p>T42 L6 r1.5 (D-L6r14-2 (1)): {@code PO_AFTER_CHANGE} pe {@code AD_PInstance} — instanța {@code runJob} pe care platforma o refuză
 * cu 409 își eliberează imediat intrările din rezervă ({@code TabeleExtractie.laSalvareInstanta}), nu la expirare.
 */
public class EvaAuditPostareEvents extends AbstractEventHandler {

    @Override
    protected void initialize() {
        registerEvent(IEventTopics.DOC_BEFORE_POST);
        registerTableEvent(IEventTopics.PO_BEFORE_NEW, org.compiere.model.MPInstancePara.Table_Name);
        registerTableEvent(IEventTopics.PO_BEFORE_CHANGE, org.compiere.model.MPInstancePara.Table_Name);
        registerTableEvent(IEventTopics.PO_AFTER_CHANGE, org.compiere.model.MPInstance.Table_Name);
    }

    @Override
    protected void doHandleEvent(Event event) {
        PO po = getPO(event);
        if (org.compiere.model.MPInstancePara.Table_Name.equalsIgnoreCase(po.get_TableName())) {
            com.eva.ro.contab.audit.extractie.TabeleExtractie.ascundeLaSalvare(po);   // D-T6: textul liber nu ajunge în clar în bază
            return;
        }
        if (org.compiere.model.MPInstance.Table_Name.equalsIgnoreCase(po.get_TableName())) {
            com.eva.ro.contab.audit.extractie.TabeleExtractie.laSalvareInstanta(po);   // r1.5 D-L6r14-2: 409 pe runJob ⇒ rezerva eliberată
            return;
        }
        Properties ctx = Env.getCtx();
        int rol = Env.getAD_Role_ID(ctx);
        // T42 L6: rolul de audit recunoscut după NUME sau după MARCAJ (rol manual cu EVA_AuditSalveaza — rezistă la redenumire)
        if (!com.eva.ro.contab.audit.GardaAudit.rolAudit(rol))
            return;
        Map<String, Object> det = new LinkedHashMap<>();
        det.put("tabela", po.get_TableName());
        det.put("record", po.get_ID());
        JurnalAudit.scrie(ctx, po.getAD_Client_ID(), null, ACTIUNE, po.get_Table_ID(), po.get_ID(), null, JurnalAudit.REFUZ, MOTIV,
                Instantaneu.json(det, Set.of()), null);
        addErrorMessage(event, Etichete.t(MOTIV));
    }

    /** Acțiunea din jurnal (forma «&lt;proces&gt;:&lt;operație&gt;»). */
    public static final String ACTIUNE = "Doc:POSTARE";
    /** Cheia refuzului (etichetă RO / EN). */
    public static final String MOTIV = "t42.refuz.postare";

    /** Decizia pură pe NUME (partea «nume» a {@link com.eva.ro.contab.audit.GardaAudit#decizieRolAudit}; marcajul o completează). */
    public static boolean refuza(String numeRol) {
        return com.eva.ro.contab.audit.GardaAudit.decizieRolAudit(numeRol, false, false);
    }
}
