    /** Candidații {@link #SQL_TAXE_COTA} (id, nume, valabil de la), legați de firmă. Doar citire. */
    static java.util.List<Object[]> taxeCota(java.math.BigDecimal cota, int client, boolean vanzare, java.sql.Timestamp laData)
            throws java.sql.SQLException {
        java.util.List<Object[]> cand = new java.util.ArrayList<>();
        try (java.sql.PreparedStatement ps = DB.prepareStatement(SQL_TAXE_COTA, null)) {
            ps.setInt(1, client);
            ps.setBigDecimal(2, cota);
            ps.setString(3, vanzare ? "S" : "P");
            ps.setTimestamp(4, laData);
            try (java.sql.ResultSet rs = ps.executeQuery()) {
                while (rs.next())
                    cand.add(new Object[]{rs.getInt(1), rs.getString(2), rs.getTimestamp(3)});
            }
        }
        return cand;
    }

