                Map<Integer, BigDecimal> pe = new LinkedHashMap<>();
                for (SetLista.LinieComponenta x : l.componente())
                    pe.merge(x.produs(), x.cantitate(), BigDecimal::add);
                for (Map.Entry<Integer, BigDecimal> e : pe.entrySet())
                    cereri.add(new RezervareStoc.LinieCerere(l.idLinie(), e.getKey(), gestiune, e.getValue()));
            } else if (l.stocabil())
                cereri.add(new RezervareStoc.LinieCerere(l.idLinie(), l.produs(), gestiune, l.cantitate()));
        return cereri;
