    /** Citirile stocului pe canal; producția = {@link #surse} (firma, sursa, canalul și tranzacția legate la construire). */
    interface SurseStoc {
        boolean esteSet(int produs);

        List<SetLista.Componenta> componente(int set);

        StocBrut brut(int produs);

        /** Cererea liniilor-set pe componentă ({@link SetLista#cerereComponenta}, funcția unică R20), cu filtrul consumatorului. */
        BigDecimal cerereSet(int componenta, SetLista.FiltruCerere filtru);

        long rezerva();

        Map<String, String> reguli();
    }

    /** Cârligul testului (vizibil doar în pachet, implicit {@code null}, 0 atribuiri în {@code src/}): dubla surselor. */
    static SurseStoc surseTest;

    /**
     * Decizia (fără bază): setul ⇒ {@link SetLista#disponibilSet} peste {@link #stocArticol} al fiecărei componente (R8; rezerva și
     * regulile canalului se aplică pe componentă, în formula ei); altfel {@link #stocArticol}. Setul invalid ({@link SetLista.Refuz} din
     * {@code componente}) ⇒ 0: nu se poate vinde, iar fișa celorlalte articole merge mai departe.
     */
    static long stocCuSet(int produs, SurseStoc s) {
        if (!s.esteSet(produs))
            return stocArticol(produs, s);
        List<SetLista.Componenta> c;
        try {
            c = s.componente(produs);
        } catch (SetLista.Refuz e) {
            return 0L;   // setul devenit invalid între esteSet și componente (orchestrator 28.10, H-RR): nu se vinde ⇒ disponibil 0, nu eroare a fișei
        }
        Map<Integer, BigDecimal> disp = new LinkedHashMap<>();
        for (SetLista.Componenta x : c)
            disp.put(x.produs(), BigDecimal.valueOf(stocArticol(x.produs(), s)));
        return SetLista.disponibilSet(disp, c);
    }

    /** Formula pe articol (§6.3) cu cererea seturilor nelivrate fără comandă emisă adunată la comenzile nelivrate (R10). */
    static long stocArticol(int produs, SurseStoc s) {
        StocBrut b = s.brut(produs);
        BigDecimal cerere = s.cerereSet(produs, SetLista.FiltruCerere.NELIVRATE_FARA_COMANDA);
        return FisaCanalCalcul.stocCalculat(b.peGestiuni(), b.rezervari(), b.comenzi().add(cerere), s.rezerva(), s.reguli());
    }

    /** Sursele de producție, legate de firmă, sursă, canal și tranzacția procesului (X257); cârligul testului, dacă e pus. */
