    /** Documentele oglindite (04_ F-7). */
    public static final String[] TABELE = {"M_InOut", "M_Inventory", "M_Movement", "M_Production"};

    @Override
    protected void initialize() {
        for (String t : TABELE)
            registerTableEvent(IEventTopics.DOC_AFTER_COMPLETE, t);
    }

    @Override
    protected void doHandleEvent(Event event) {
        if (!IEventTopics.DOC_AFTER_COMPLETE.equals(event.getTopic()))
            return;
        PO po = getPO(event);
        String eroare = OglindaWms.laCompletare(po);
        if (eroare != null)
            addErrorMessage(event, eroare);
    }
