 * C127-d (A50, avizul AVIZ_C127D_TIP_DOCUMENT cond. 2 / 4 / 6) — validările de model:
 * <ul>
 *   <li>GL_Journal de tipul «EvA — notă de închidere» fără marcajul INCHIDERE-* → refuzat (tipul e rezervat notelor de
 *       sistem; notele manuale ale contabilului rămân pe GL Journal, nereactivabil);</li>
 *   <li>schimbarea tipului de document pe o notă deja înregistrată → refuzată (migrarea doar prin storno + notă nouă);</li>
 *   <li>EVA_NotaReinchidere și EVA_JurnalVersiuni sunt DOAR cu adăugare: modificarea și ștergerea sunt refuzate.</li>
 * </ul>
 */
public class EvaNoteInchidereEvents extends AbstractEventHandler {

    @Override
    protected void initialize() {
        registerTableEvent(IEventTopics.PO_BEFORE_NEW, "GL_Journal");
        registerTableEvent(IEventTopics.PO_BEFORE_CHANGE, "GL_Journal");
        registerTableEvent(IEventTopics.PO_BEFORE_CHANGE, NotaReinchidereModel.TABELA);
        registerTableEvent(IEventTopics.PO_BEFORE_DELETE, NotaReinchidereModel.TABELA);
        registerTableEvent(IEventTopics.PO_BEFORE_CHANGE, JurnalVersiuniModel.TABELA);
        registerTableEvent(IEventTopics.PO_BEFORE_DELETE, JurnalVersiuniModel.TABELA);
    }

    @Override
    protected void doHandleEvent(Event event) {
        PO po = getPO(event);
        String tabela = po.get_TableName();
        if (NotaReinchidereModel.TABELA.equalsIgnoreCase(tabela) || JurnalVersiuniModel.TABELA.equalsIgnoreCase(tabela)) {
            addErrorMessage(event, tabela + " e doar cu adăugare (urmă de audit / jurnal de versiuni, OMFP 2634/2015"
                    + " pct. 58 lit. n), pct. 61): rândurile nu se modifică și nu se șterg");
            return;
        }
        // GL_Journal
        int client = po.getAD_Client_ID();
        int tip = po.get_ValueAsInt("C_DocType_ID");
        if (IEventTopics.PO_BEFORE_CHANGE.equals(event.getTopic()) && po.is_ValueChanged("C_DocType_ID")
                && po.get_ValueOld("Processed") != null && Boolean.TRUE.equals(po.get_ValueOld("Processed"))) {
            addErrorMessage(event, "tipul de document al unei note deja înregistrate nu se schimbă (C127-d: trecerea pe"
                    + " tipul «" + TipNotaInchidere.NUME + "» se face doar prin storno + notă nouă)");
            return;
        }
        if (TipNotaInchidere.esteTipul(client, tip)) {
            if (IEventTopics.PO_BEFORE_NEW.equals(event.getTopic()) && !TipNotaInchidere.permis()) {
                addErrorMessage(event, "tipul «" + TipNotaInchidere.NUME + "» se creează doar din închiderile EvA"
                        + " (NotaInchidere), nu din fereastra de note; notele manuale se înregistrează pe GL Journal");
                return;
            }
            String d = po.get_ValueAsString("Description");
            // «RESET-…» = re-descrierea perechii storno din «Resetare închideri» (cod EvA, cu permisiunea firului)
            if (d == null || !(d.startsWith("INCHIDERE-") || (d.startsWith("RESET-") && TipNotaInchidere.permis())))
                addErrorMessage(event, "tipul «" + TipNotaInchidere.NUME + "» e rezervat notelor de închidere generate de"
                        + " EvA (marcaj INCHIDERE-*); notele manuale se înregistrează pe GL Journal");
        }
    }
}

