    /** Canalul comenzii (spec §3.4 pasul 1): campania &gt; 0 ⇒ canalul campaniei; altfel canalul grupei partenerului (D-316-25). */
    static Canal canalComenzii(int client, int campanie, int partener, String trx, Surse s) {
        return campanie > 0 ? s.canalCampaniei(client, campanie, trx) : s.canalPartener(client, partener, trx);
    }

    /**
     * Lipiciul antetului (fără PO, executat de test pe valoare — X216): doar vânzarea; pe salvare doar la antet nou sau la schimbarea
     * campaniei / partenerului / listei / termenului; firma ≤ 0 ⇒ {@code t316.refuz.firma} (X207); structura absentă ⇒ nimic
     * (T316 (a)); la {@code DOC_BEFORE_PREPARE} DOAR creditul (D-316-31); altfel {@link #decizieLista} și scrierile ei.
     */
    static String comandaB2B(String topic, Comanda c, Surse s, ScriereComanda w) {
        if (!c.vanzare())
            return null;
        boolean pregatire = IEventTopics.DOC_BEFORE_PREPARE.equals(topic);
        boolean nou = IEventTopics.PO_BEFORE_NEW.equals(topic);
        if (!pregatire && !nou && !c.schimbat())
            return null;
        if (c.client() <= 0)
            return Etichete.t(K_FIRMA);
        if (!s.structura(c.trx()))
            return null;
        Canal canal = canalComenzii(c.client(), c.campanie(), c.partener(), c.trx(), s);
        if (!esteB2B(canal))
            return null;
        if (pregatire)
            return credit(c, canal, s);
        int linii = nou ? 0 : s.liniiCuProdus(c.client(), c.id(), c.trx());
        Decizie d = decizieLista(canal, c.lista(), s.termenPartener(c.client(), c.partener(), c.trx()), linii, c.canalSchimbat());
        if (d == null)
            return null;
        if (d.refuz() != null)
            return Etichete.t(d.refuz());
        if (d.campanie() > 0 && d.campanie() != c.campanie())
            w.campanie(d.campanie());
        if (d.lista() != c.lista())
            w.lista(d.lista());
        if (d.termen() > 0 && d.termen() != c.termen())
            w.termen(d.termen());
        return null;
    }

