 * {@code AUTO} cu «Validez…» al omului), iar liniile valului se cumulează pe cheie ({@link RezervareStoc#liniiPesteStoc}):
 * o linie care ar duce SUMA peste stoc iese din val (ROȘIE, {@code V18:stoc_insuficient}); ÎNAINTE de
 * {@code processIt(Complete)} pe livrare, suma pe cheie se reverifică cu {@link RezervareStoc#lasaNegativ} — adevărat ⇒
 * rollback la savepoint, 0 documente, liniile ROȘII, mesajul {@code vanzari.stoc.negativ_interzis}. Pe fiecare locație se
 * descarcă cel mult cât are (linia se împarte pe locații), deci nicio locație nu ajunge negativă.
 *
 * <p>Intrarea abstractă {@link ComandaDeEmis} (R17, refolosibilă); {@code EVA_ComandaSite} se citește în
 * {@code ValideazaComenzi}, nu aici. Partenerul (§6.4.2): PJ căutat după CUI în {@code C_BPartner.TaxID}, altfel creat; PF
 * cu cheia {@code SITE-<32 hex>} = SHA-256(sursă + «:» + {@code customer.ref}), {@code TaxID} = 13 zerouri; datele
 * personale stau DOAR în {@code C_BPartner} / {@code C_Location}.
 */
public final class GeneratorDocumente {

    private GeneratorDocumente() {
    }

    /** Partenerul facturii (date doar în memorie, scrise DOAR în {@code C_BPartner} / {@code C_Location}). */
    public record Partener(boolean pj, String cui, String cheiePf, String nume, String adresa, String oras, String judet,
            String codPostal, String tara) {
        @Override
        public String toString() {
            return "Partener[pj=" + pj + "]";
        }
    }

    /**
     * O linie a valului: id-ul liniei site, articolul, cantitatea, prețul BRUT în lei, cota legală (%), stocabil. Seriile
     * (instanțele {@code M_AttributeSetInstance} pe liniile livrării) = faza J (J-BE2); la B, V17 oprește linia fără serii.
     */
    public record Linie(int idLinie, int produs, BigDecimal cantitate, BigDecimal pretBrutLei, int cotaLegala, boolean stocabil,
            String tipSerie, List<SeriiArticole.Serie> serii, List<SetLista.LinieComponenta> componente) {
        /** Constructorul de dinainte de P01.T203 (fără serii): tipul de serie {@code null}, 0 serii. */
        public Linie(int idLinie, int produs, BigDecimal cantitate, BigDecimal pretBrutLei, int cotaLegala, boolean stocabil) {
            this(idLinie, produs, cantitate, pretBrutLei, cotaLegala, stocabil, null, List.of());
        }

        /** Constructorul de dinainte de P01.T354 (linia nu e set: 0 componente). */
        public Linie(int idLinie, int produs, BigDecimal cantitate, BigDecimal pretBrutLei, int cotaLegala, boolean stocabil,
                String tipSerie, List<SeriiArticole.Serie> serii) {
            this(idLinie, produs, cantitate, pretBrutLei, cotaLegala, stocabil, tipSerie, serii, List.of());
        }

        /** P01.T354 A: linia setului vândut pe componente ({@link SetLista#explodeaza}, D-ORC-1 V2). */
        public boolean esteSet() {
            return componente != null && !componente.isEmpty();
        }
    }

    // # P01.T354 A — început (P01.C03.T0028, plan §5.1 (3), D-ORC-1 V2): setul pe documente

    /**
     * Liniile valului văzute de factură (pură): linia setului se facturează ca o linie stocabilă — liniile ei de factură = liniile livrării
     * (componentele, cu prețul și taxa liniilor de comandă ale componentelor); celelalte linii, neschimbate (aceleași obiecte).
     */
    static List<Linie> pentruFactura(List<Linie> val) {
        List<Linie> r = new ArrayList<>();
        for (Linie l : val)
            r.add(l.esteSet() ? new Linie(l.idLinie(), l.produs(), l.cantitate(), l.pretBrutLei(), l.cotaLegala(), true, null, List.of(),
                    l.componente()) : l);
        return r;
    }

    /** Cererile de stoc ale valului (pură): articolul stocabil = o cerere; setul = câte o cerere pe componentă (cantitățile adunate). */
    static List<RezervareStoc.LinieCerere> cereriVal(List<Linie> linii, int gestiune) {
        List<RezervareStoc.LinieCerere> cereri = new ArrayList<>();
        for (Linie l : linii)
            if (l.esteSet()) {
                Map<Integer, BigDecimal> pe = new LinkedHashMap<>();
                for (SetLista.LinieComponenta x : l.componente())
                    pe.merge(x.produs(), x.cantitate(), BigDecimal::add);
                for (Map.Entry<Integer, BigDecimal> e : pe.entrySet())
                    cereri.add(new RezervareStoc.LinieCerere(l.idLinie(), e.getKey(), gestiune, e.getValue()));
            } else if (l.stocabil())
                cereri.add(new RezervareStoc.LinieCerere(l.idLinie(), l.produs(), gestiune, l.cantitate()));
        return cereri;
    }

    /** Stocul pe locații minus ce a luat deja livrarea în curs din fiecare locație (pură; locațiile golite dispar, ordinea rămâne). */
    static Map<Integer, BigDecimal> faraConsumat(Map<Integer, BigDecimal> loc, Map<Integer, BigDecimal> consumat) {
        Map<Integer, BigDecimal> m = new LinkedHashMap<>();
        for (Map.Entry<Integer, BigDecimal> e : loc.entrySet()) {
            BigDecimal q = e.getValue().subtract(consumat == null ? BigDecimal.ZERO : consumat.getOrDefault(e.getKey(), BigDecimal.ZERO));
            if (q.signum() > 0)
                m.put(e.getKey(), q);
        }
        return m;
    }
    // # P01.T354 A — sfârșit

    // # T203 — început (P01.T203 A-6, 74 §6.5 pas 4; D-33): seriile pe liniile documentelor

    /** O bucată a liniei: instanța ({@code 0} = se creează la livrare, tipul 2), seria și cantitatea. */
    public record Bucata(int instanta, String serie, BigDecimal cantitate) {
    }

    /**
     * Împărțirea liniei pe bucăți (pură, M-17): fără tip de serie ⇒ o bucată cu toată cantitatea (instanța 0, fără serie); tipul 2
     * ({@code S}) ⇒ câte o bucată de 1 pe serie, instanța 0 (creată la livrare); tipul 3 ({@code Y}) ⇒ câte o bucată de 1 pe serie,
     * cu instanța aleasă; numărul seriilor ≠ cantitatea (sau cantitatea nu e întreagă) ⇒ {@code null} (refuz).
     */
    public static List<Bucata> bucati(String tip, List<SeriiArticole.Serie> serii, BigDecimal cantitate) {
        if (!SeriiArticole.TIP_LA_VANZARE.equals(tip) && !SeriiArticole.TIP_DIN_STOC.equals(tip))
            return List.of(new Bucata(0, null, cantitate));
        if (serii == null || cantitate == null || cantitate.signum() <= 0 || cantitate.stripTrailingZeros().scale() > 0
                || cantitate.compareTo(BigDecimal.valueOf(serii.size())) != 0)
            return null;
        List<Bucata> l = new ArrayList<>();
        for (SeriiArticole.Serie x : serii)
            l.add(new Bucata(SeriiArticole.TIP_DIN_STOC.equals(tip) ? x.instanta() : 0, x.serie(), BigDecimal.ONE));
        return l;
    }

    /** D-33 (pur): tipul 3 ({@code Y}) ⇒ câte o linie de comandă pe serie, cu instanța aleasă (refuzul nativ «Attribute Set Mandatory»). */
    public static boolean liniePeSerie(String tip) {
        return SeriiArticole.TIP_DIN_STOC.equals(tip);
    }

    /** O bucată pusă pe locație (livrarea). */
    public record Plasare(int locator, Bucata bucata) {
    }

    /**
     * Plasarea bucăților pe locațiile alese de {@link #peLocatii} (pură, tipul 2 și fără serie): fără serie ⇒ o plasare pe locație cu
     * cantitatea ei (ca înainte de T203); bucăți de 1 ⇒ câte o plasare pe bucată, consumând locațiile în ordine. Suma locațiilor
     * ≠ numărul bucăților ⇒ {@code null}.
     */
    public static List<Plasare> plaseaza(List<Bucata> bucati, Map<Integer, BigDecimal> loc) {
        List<Plasare> l = new ArrayList<>();
        if (bucati.size() == 1 && bucati.get(0).serie() == null) {
            for (Map.Entry<Integer, BigDecimal> e : loc.entrySet())
                l.add(new Plasare(e.getKey(), new Bucata(0, null, e.getValue())));
            return l;
        }
        int i = 0;
        for (Map.Entry<Integer, BigDecimal> e : loc.entrySet())
            for (BigDecimal q = e.getValue(); q.signum() > 0; q = q.subtract(BigDecimal.ONE)) {
                if (i >= bucati.size() || q.compareTo(BigDecimal.ONE) < 0)
                    return null;
                l.add(new Plasare(e.getKey(), bucati.get(i++)));
            }
        return i == bucati.size() ? l : null;
    }

