    public static final String SQL_LOCATIE_INSTANTA = "SELECT coalesce(min(s.m_locator_id),0) FROM m_storageonhand s JOIN m_locator lo"
            + " ON lo.m_locator_id=s.m_locator_id AND lo.ad_client_id=s.ad_client_id WHERE s.ad_client_id=? AND lo.m_warehouse_id=?"
            + " AND s.m_product_id=? AND s.m_attributesetinstance_id=? AND s.qtyonhand>=1";

    /** Instanța nouă a unei bucăți de tipul 2 (SerNo), pe setul articolului, organizația 0. */
    private static int instantaNoua(Properties ctx, int produs, String serie, String trx) {
        org.compiere.model.MAttributeSetInstance a = new org.compiere.model.MAttributeSetInstance(ctx, 0,
                org.compiere.model.MProduct.get(ctx, produs).getM_AttributeSet_ID(), trx);
        a.setAD_Org_ID(0);
        a.setSerNo(serie);
        a.setDescription();
        a.saveEx();
        return a.getM_AttributeSetInstance_ID();
    }
    // # T203 — sfârșit

